/* ===== tx10.js — Writer W9: Hill Country towns & the roads =====
 Cities: sanmarcos (San Marcos & Wimberley), luckenbach (Luckenbach).
 Town characters: ofelia (San Marcos river keeper, 3 stages), june (Wimberley egg farmer, 3 stages), walt (Luckenbach fiddler, 3 stages).
 Road regulars (met only through ROAD_EVENTS, one stage per meeting, each stage on a different set of highways):
   hutchins (team truckers), otis (Greyhound driver), gabi (state trooper). Stage flag: S.flags.tx10_<id> (0–3).
 Highway events: 12, one or more per main road, gated on c.via with a region/miles fallback.
 Dish: gpotato (German potato salad, from Walt). Perks: dairy ×0.8 (June), pork ×0.8 (the Hutchinses).
*/
Object.assign(DISH,{
 gpotato:{n:['德式热土豆沙拉','German potato salad','Salada de batata à alemã'],ing:'pork',price:6,unlock:true,pref:{ranch:2,family:3,trucker:2,luso:1}}
});
Object.assign(NPCS,{
 ofelia:{n:['奥费利娅·坎图','Ofelia Cantú','Ofelia Cantú'],s:['菲老师','Miss Fe','a professora Fe'],p:['她','her','ela'],role:['圣马科斯河的退休生物老师兼护河潜水员','Retired biology teacher and volunteer river diver on the San Marcos','Professora de biologia reformada e mergulhadora voluntária no rio San Marcos'],loc:'sanmarcos'},
 june:{n:['琼·奥尔布雷克特','June Albrecht','June Albrecht'],s:['琼','June','June'],p:['她','her','ela'],role:['温伯利柏树溪边养鸡养羊的农妇','Hen-and-goat farmer on Cypress Creek, Wimberley','Criadora de galinhas e cabras junto ao Cypress Creek, Wimberley'],loc:'sanmarcos'},
 walt:{n:['沃尔特·凯斯勒','Walt Kessler','Walt Kessler'],s:['沃尔特','Walt','Walt'],p:['他','him','ele'],role:['卢肯巴赫橡树下拉小提琴的德裔老人','Old German-Texan fiddler under the Luckenbach oaks','Velho violinista teuto-texano debaixo dos carvalhos de Luckenbach'],loc:'luckenbach'},
 hutchins:{n:['朗尼和达琳·哈钦斯','Lonnie & Darlene Hutchins','Lonnie e Darlene Hutchins'],s:['哈钦斯夫妇','the Hutchinses','os Hutchins'],p:['他们','them','eles'],role:['开冷藏半挂车的夫妻搭档','Husband-and-wife team driving a reefer semi','Casal que conduz um camião frigorífico em equipa'],loc:'laredo'},
 otis:{n:['奥蒂斯·弗里曼','Otis Freeman','Otis Freeman'],s:['奥蒂斯','Otis','Otis'],p:['他','him','ele'],role:['开了三十多年灰狗巴士的老司机','Greyhound driver of thirty-odd years','Motorista da Greyhound há mais de trinta anos'],loc:'sanantonio'},
 gabi:{n:['加芙列拉·萨尔达尼亚','Gabriela Saldaña','Gabriela Saldaña'],s:['萨尔达尼亚警官','Trooper Saldaña','a agente Saldaña'],p:['她','her','ela'],role:['德州公路巡警','Texas Highway Patrol trooper','Agente da Patrulha Rodoviária do Texas'],loc:'waco'}
});
(function(){
const DAY=()=>S.week*10+S.day;
const daily=k=>()=>S.flags['tx10_d_'+k]!==DAY()||t(`今天已经做过了，明天再来`,`Already done today — come back tomorrow`,`Já fizeste isto hoje — volta amanhã`);
const stamp=k=>{S.flags['tx10_d_'+k]=DAY()};
const AND=(...f)=>()=>{for(const g of f){const r=g();if(r!==true)return r}return true};
const SEAS=(a,b,z,e,p)=>()=>inSeason(a,b)||t(z,e,p);
const W=()=>(S.tripWith&&NPCS[S.tripWith])?S.tripWith:null;
const MET=id=>!!(S.npc[id]&&S.npc[id].met);
const ONL=n=>{S.online=clamp(S.online+n,0,100)};
const MEET=id=>{const r=rel(id);if(r)r.met=true};
const sc=(title,meta,text,choices)=>({title,meta,text,choices});
const ST=k=>S.flags['tx10_'+k]||0;
const VIS=c=>(S.visited&&S.visited[c])||0;
const ADV=(k,c)=>{S.flags['tx10_'+k]=ST(k)+1;if(c)S.flags['tx10_'+k+'_v']=VIS(c)};
const STAGE=(k,c,max)=>()=>{if(ST(k)>=max)return daily(k)();const v=S.flags['tx10_'+k+'_v'];if(v!==undefined&&VIS(c)<=v)return t(`这一趟已经聊过了，下次来再接着说`,`You've talked this trip — pick it up next visit`,`Já falaram nesta viagem — continuam na próxima visita`);return true};
function buy(title,ing,qty,mult,z,e,p){const c=cityBuy(ing,qty,mult);
 if(!c)return say(title,t(`你数了数钱包，这批货拿不下。`,`You count your cash. It won't cover the lot.`,`Contas o dinheiro. Não chega para o lote.`));
 return say(title,t(z,e,p),t(`${tt(ING[ing].n)} +${qty} · −$${c}`,`${tt(ING[ing].n)} +${qty} · −$${c}`,`${tt(ING[ing].n)} +${qty} · −$${c}`));}
function pop(title,max,mult,z,e,p){const r=popupSell(max,mult);
 if(!r.sold)return say(title,t(`冷藏箱是空的。你只好帮隔壁的人吆喝了一下午。`,`The cooler is empty. You spend the afternoon hollering for the stall next door.`,`A geleira está vazia. Passas a tarde a apregoar pela banca do lado.`),t(`先在店里进货再出门`,`Stock up at the shop before you travel`,`Abastece o restaurante antes de viajar`));
 S.rep+=r.sold>=8?2:1;
 return say(title,t(z,e,p),t(`卖出 ${r.sold} 份 · +$${r.cash} · 口碑与线上评分上升`,`Sold ${r.sold} · +$${r.cash} · reputation and rating up`,`Vendeste ${r.sold} · +$${r.cash} · reputação e avaliação sobem`));}
const C={sm:t(`圣马科斯`,`San Marcos`,`San Marcos`),wim:t(`温伯利`,`Wimberley`,`Wimberley`),lb:t(`卢肯巴赫`,`Luckenbach`,`Luckenbach`)};
const DONE=t(`这条故事线已经走完了`,`This storyline is complete`,`Esta história já terminou`);

/* ---------------- OFELIA (San Marcos) ---------------- */
function feScene(){const s=ST('ofelia'),T=t(`护河人`,`The river keeper`,`A guardiã do rio`);
 if(s===0)return sc(T,C.sm,[
  t(`你蹲在春湖边看水，一只脚踩进了浅滩里的水草。一个穿潜水服的白发女人从水里冒出来：“脚！那是德州野稻，全世界只长在这条河里！”`,`You crouch at the edge of Spring Lake and one foot slips into the waterweed in the shallows. A white-haired woman in a wetsuit surfaces. "Your foot! That's Texas wild rice — it grows in this river and nowhere else on earth!"`,`Agachas-te à beira do Spring Lake e um pé escorrega para as ervas do baixio. Uma mulher de cabelo branco, de fato de mergulho, sobe à tona. «O pé! Isso é arroz-selvagem-do-texas — só cresce neste rio, em mais lado nenhum do mundo!»`),
  t(`她叫奥费利娅·坎图，教了三十年高中生物，退休以后每个星期下水，拔外来的水草，捡啤酒罐，数小蝾螈。`,`Her name is Ofelia Cantú. She taught high-school biology for thirty years; retired, she dives every week, pulling invasive weeds, picking up beer cans, counting salamanders.`,`Chama-se Ofelia Cantú. Ensinou biologia no liceu durante trinta anos; reformada, mergulha todas as semanas, a arrancar ervas invasoras, a apanhar latas de cerveja, a contar salamandras.`)],[
  {t:t(`道歉，脱鞋下水帮她拔草`,`Apologise, kick off your shoes and help her pull weeds`,`Pedir desculpa, tirar os sapatos e ajudá-la a arrancar ervas`),fx:()=>{MEET('ofelia');addLike('ofelia',2);addTrust('ofelia',1);stat('oficio',1);stat('tex',1);ADV('ofelia','sanmarcos');log('在圣马科斯认识了菲老师','Met Miss Fe in San Marcos','Conheceste a professora Fe em San Marcos')},next:()=>say(T,t(`水一年到头都是二十二度左右，冷得你直吸气。她教你分辨：叶子细长、贴着沙子的是野稻，别碰；浮起来一团团的是外来草，连根拔。“明年再来，我考你。”`,`The water stays around seventy-two degrees all year and it takes your breath away. She shows you: long thin leaves hugging the sand are wild rice, hands off; the floating clumps are invaders, pull them by the root. "Come back and I'll test you."`,`A água anda pelos vinte e dois graus o ano inteiro e corta-te a respiração. Ela ensina-te: folhas longas e finas rentes à areia são arroz-selvagem, não se mexe; os tufos que flutuam são invasores, arrancam-se pela raiz. «Volta cá e faço-te um teste.»`),t(`认识了菲老师 · 好感 +2`,`Met Miss Fe · Liking +2`,`Conheceste a professora Fe · Afeição +2`))},
  {t:t(`${faceWord()}冲她笑一笑，说你只是个迷路的游客`,`${faceWord()}flash her a smile and say you're just a lost tourist`,`${faceWord()}sorrir-lhe e dizer que és só um turista perdido`),fx:()=>{MEET('ofelia');flirt();stat('charme',1);ADV('ofelia','sanmarcos')},next:()=>say(T,t(`“孩子，我教过两千个比你帅的十七岁男孩。”她把一只啤酒罐塞进你手里，“拿去扔了，这就算你的门票。”`,`"Honey, I've taught two thousand seventeen-year-olds prettier than you." She presses a beer can into your hand. "Go throw that out. That's your ticket."`,`«Querido, já dei aulas a dois mil miúdos de dezassete anos mais bonitos do que tu.» Mete-te uma lata de cerveja na mão. «Vai deitar isso fora. É o teu bilhete.»`),t(`认识了菲老师`,`Met Miss Fe`,`Conheceste a professora Fe`))}]);
 if(s===1)return sc(T,C.sm,[
  t(`菲老师在湖边摊开一张地图，上面一条弯弯的带子从圣安东尼奥一直画到这里。“爱德华兹含水层。山地下的雨渗进石灰岩，走好多年，最后从这两百多个泉眼冒出来。”`,`Miss Fe spreads a map by the lake: a curving band drawn from San Antonio all the way here. "The Edwards Aquifer. Rain on the Hill Country soaks into the limestone, travels for years, and comes up through these two hundred-odd springs."`,`A professora Fe estende um mapa junto ao lago: uma faixa curva desenhada desde San Antonio até aqui. «O aquífero de Edwards. A chuva do Hill Country infiltra-se no calcário, viaja durante anos e sai por estas duzentas e tal nascentes.»`),
  t(`“所以我跟学生讲：你往地里倒什么，迟早会在别人的杯子里喝到。”你想起罐头厂，想起若泽信里那句“水的颜色不对”。`,`"So I told my students: whatever you pour into the ground, sooner or later somebody drinks it." You think of the cannery, of the line in José's letter: "the water was the wrong colour."`,`«Por isso eu dizia aos alunos: o que deitas na terra, mais cedo ou mais tarde alguém o bebe.» Pensas na fábrica, na frase da carta do José: «a água tinha a cor errada».`)],[
  {t:t(`把罐头厂废水的事告诉她`,`Tell her about the cannery wastewater`,`Contar-lhe as águas residuais da fábrica`),fx:()=>{addTrust('ofelia',2);S.flags.tx10_feKnows=1;ADV('ofelia','sanmarcos')},next:()=>say(T,t(`她听完，摘下潜水镜，用指甲在地图上你们镇的位置敲了两下。“那片不在含水层上，但地下水不认地图。下次来，我教你怎么取一份法庭上站得住的水样。”`,`She hears you out, pulls off her mask and taps your town on the map twice with a fingernail. "That's off the aquifer, but groundwater doesn't read maps. Next time, I'll teach you to take a sample that holds up in court."`,`Ouve-te até ao fim, tira a máscara e bate duas vezes com a unha no sítio da tua vila. «Isso fica fora do aquífero, mas a água subterrânea não lê mapas. Da próxima vez ensino-te a recolher uma amostra que aguente num tribunal.»`),t(`信任 +2`,`Trust +2`,`Confiança +2`))},
  {t:t(`只问她怎么数小蝾螈`,`Just ask how she counts the salamanders`,`Perguntar só como conta as salamandras`),fx:()=>{addLike('ofelia',1);stat('saud',-1);stat('oficio',1);ADV('ofelia','sanmarcos')},next:()=>say(T,t(`圣马科斯蝾螈比你的小指还短，背是棕色的，一辈子住在泉眼边。她数了二十年。“数东西是最诚实的爱，”她说，“你数你的客人，我数我的蝾螈。”`,`The San Marcos salamander is shorter than your little finger, brown-backed, and spends its life by the springs. She's counted them for twenty years. "Counting is the most honest kind of love," she says. "You count your customers, I count my salamanders."`,`A salamandra de San Marcos é mais curta que o teu dedo mindinho, de dorso castanho, e vive a vida inteira junto às nascentes. Ela conta-as há vinte anos. «Contar é a forma mais honesta de amor», diz. «Tu contas os clientes, eu conto as salamandras.»`))}]);
 if(s===2)return sc(T,C.sm,[
  t(`今天是护河队的大清理日。四十个志愿者，学生、退伍兵、带着孙子的老人，从河里拖出购物车、轮胎和一辆儿童自行车。中午他们饿得要命。`,`It's the river crew's big cleanup day. Forty volunteers — students, veterans, grandparents with grandkids — haul shopping carts, tyres and a child's bike out of the river. By noon they're starving.`,`É o grande dia de limpeza da equipa do rio. Quarenta voluntários — estudantes, veteranos, avós com netos — tiram do rio carrinhos de compras, pneus e uma bicicleta de criança. Ao meio-dia estão esfomeados.`)],[
  {t:t(`在河边支起炭炉，给四十个人烤猪排包`,`Set up a grill by the river and make bifanas for forty`,`Montar uma grelha junto ao rio e fazer bifanas para quarenta`),req:()=>S.inv.pork>=4||NEED(t(`库存猪肉 4`,`4 pork in stock`,`4 de porco em stock`)),fx:()=>{S.inv.pork-=4;addLike('ofelia',2);addTrust('ofelia',1);S.rep+=3;ONL(4);ADV('ofelia','sanmarcos');S.flags.tx10_feDone=1;if(S.flags.tx10_feKnows)S.flags.tx10_sample=1},next:()=>say(T,[t(`德州州立大学的学生报记者拍了一张你在烟里翻肉的照片，第二天登在网上：“葡萄牙人喂饱了护河队”。`,`A reporter from the Texas State student paper snaps you flipping meat in the smoke; next day it's online: "Portuguese grill feeds the river crew."`,`Um repórter do jornal dos estudantes da Texas State fotografa-te a virar carne no fumo; no dia seguinte está online: «Churrasqueira portuguesa alimenta a equipa do rio.»`),
    S.flags.tx10_feKnows?t(`散场时菲老师塞给你一只盒子：消毒瓶、标签、封条。“两个人在场，写日期，签名，封好，冷藏。下次你在罐头厂边上取水，就这么取。”`,`As things wind down Miss Fe hands you a box: sterile bottles, labels, seals. "Two witnesses, date it, sign it, seal it, keep it cold. When you sample near that cannery, do it exactly like this."`,`No fim, a professora Fe dá-te uma caixa: frascos esterilizados, etiquetas, selos. «Duas testemunhas, data, assinatura, selo, frio. Quando recolheres água perto da fábrica, faz exatamente assim.»`):t(`菲老师拍拍你肩膀：“明年清理日，你还来。这不是问句。”`,`Miss Fe claps your shoulder. "Next year's cleanup, you're coming. That wasn't a question."`,`A professora Fe dá-te uma palmada no ombro. «Para o ano, na limpeza, vens. Não foi uma pergunta.»`)],S.flags.tx10_feKnows?t(`口碑 +3 · 线上评分 +4 · 得到取样工具`,`Reputation +3 · Rating +4 · Sampling kit`,`Reputação +3 · Avaliação +4 · Kit de recolha`):t(`口碑 +3 · 线上评分 +4`,`Reputation +3 · Rating +4`,`Reputação +3 · Avaliação +4`))},
  {t:t(`没带货，就下水跟他们一起拖轮胎`,`No stock — get in the water and haul tyres with them`,`Sem mercadoria — entrar na água e arrastar pneus com eles`),fx:()=>{addLike('ofelia',1);stat('tex',2);S.energy=Math.max(0,S.energy-1);S.rep+=1;ADV('ofelia','sanmarcos');S.flags.tx10_feDone=1},next:()=>say(T,t(`你拖上来一只满是泥的轮胎，大家给你鼓掌。菲老师说：“下次带吃的。”`,`You drag up a tyre full of mud and everyone applauds. Miss Fe says: "Next time bring food."`,`Puxas um pneu cheio de lama e todos aplaudem. A professora Fe diz: «Da próxima traz comida.»`),t(`德州味 +2 · 口碑 +1`,`Texan +2 · Reputation +1`,`Texano +2 · Reputação +1`))}]);
 return sc(T,C.sm,[pick([t(`菲老师在浅滩里给一群小学生讲野稻。她远远朝你竖了个拇指。`,`Miss Fe is in the shallows teaching a class of kids about wild rice. She gives you a thumbs-up from afar.`,`A professora Fe está no baixio a ensinar um grupo de miúdos sobre o arroz-selvagem. Faz-te um polegar para cima ao longe.`),t(`“今年的蝾螈比去年多了九只，”菲老师说，“你的客人呢？”`,`"Nine more salamanders than last year," says Miss Fe. "And your customers?"`,`«Mais nove salamandras do que no ano passado», diz a professora Fe. «E os teus clientes?»`)])],[{t:t(`陪她坐一会儿`,`Sit with her a while`,`Ficar um bocado com ela`),fx:()=>{stamp('ofelia');addLike('ofelia',1);stat('saud',-1)}}]);
}

/* ---------------- JUNE (Wimberley) ---------------- */
function juneScene(){const s=ST('june'),T=t(`柏树溪的鸡蛋`,`Eggs from Cypress Creek`,`Ovos do Cypress Creek`);
 if(s===0)return sc(T,C.wim,[
  t(`温伯利广场边上，一个晒得黝黑的女人坐在皮卡后斗里卖鸡蛋和羊奶。她敲开一个给你看：蛋黄橙得像落日。`,`At the edge of the Wimberley square, a sun-dark woman sells eggs and goat's milk from her pickup bed. She cracks one to show you: the yolk is orange as a sunset.`,`À beira da praça de Wimberley, uma mulher muito morena do sol vende ovos e leite de cabra na caixa da carrinha. Parte um para te mostrar: a gema é laranja como um pôr do sol.`),
  t(`“我的鸡吃蚱蜢和山核桃，”她说，“你是做什么的？”你说用这种蛋能做出全德州最好的葡式蛋挞。她哼了一声：“说大话的我见多了。”`,`"My hens eat grasshoppers and pecans," she says. "What's your line?" You say with eggs like these you could make the best custard tarts in Texas. She snorts. "I've met plenty of big talkers."`,`«As minhas galinhas comem gafanhotos e nozes-pecã», diz. «E tu, fazes o quê?» Dizes que com ovos assim fazias os melhores pastéis de nata do Texas. Ela bufa. «Já conheci muitos fanfarrões.»`)],[
  {t:t(`当场买下她一车的蛋奶`,`Buy her whole load of eggs and milk on the spot`,`Comprar-lhe a carga toda de ovos e leite`),fx:()=>{MEET('june');addLike('june',2);ADV('june','sanmarcos');log('在温伯利认识了琼','Met June in Wimberley','Conheceste a June em Wimberley')},next:()=>buy(T,'dairy',8,1.1,`“好吧，大话王。”她帮你把箱子搬上车，“下次来我的农场，柏树溪往上游走，看见红顶谷仓就是。”`,`"All right, big talker." She helps load the crates. "Next time come out to the farm — up Cypress Creek, look for the red-roofed barn."`,`«Está bem, fanfarrão.» Ajuda-te a carregar as caixas. «Da próxima vem à quinta — Cypress Creek acima, procura o celeiro de telhado vermelho.»`)},
  {t:t(`跟她聊鸡`,`Talk chickens with her`,`Falar de galinhas com ela`),fx:()=>{MEET('june');addLike('june',1);addTrust('june',1);stat('tex',1);ADV('june','sanmarcos');log('在温伯利认识了琼','Met June in Wimberley','Conheceste a June em Wimberley')},next:()=>say(T,t(`你外婆在阿尔法马的阳台上养过三只鸡，邻居投诉了二十年。琼笑得差点从后斗上掉下来。“来农场吧，我那儿有四十只，没人投诉。”`,`Your grandmother kept three hens on a balcony in Alfama and the neighbours complained for twenty years. June nearly falls off the tailgate laughing. "Come out to the farm. I've got forty and nobody complains."`,`A tua avó tinha três galinhas numa varanda em Alfama e os vizinhos queixaram-se durante vinte anos. A June quase cai da caixa da carrinha a rir. «Vem à quinta. Tenho quarenta e ninguém se queixa.»`),t(`认识了琼 · 信任 +1`,`Met June · Trust +1`,`Conheceste a June · Confiança +1`))}]);
 if(s===1)return sc(T,C.wim,[
  t(`红顶谷仓是新的，木头还是浅色。溪边一棵老柏树的树干上钉着一块铁皮，比你的头顶还高出一大截。“那年阵亡将士纪念日，布兰科河一夜之间涨到那里，”琼说，“旧谷仓、羊、半个邻居家，都冲走了。”`,`The red-roofed barn is new; the wood's still pale. On an old cypress by the creek a tin plate is nailed far above your head. "That Memorial Day the Blanco came up to there overnight," June says. "The old barn, the goats, half the neighbour's house — all gone."`,`O celeiro de telhado vermelho é novo; a madeira ainda está clara. Num cipreste velho junto ao ribeiro há uma chapa pregada muito acima da tua cabeça. «Naquele Memorial Day o Blanco subiu até ali numa noite», diz a June. «O celeiro velho, as cabras, meia casa do vizinho — tudo.»`),
  t(`“第二天早上，全镇的人开着皮卡带着电锯来了。没人问要不要帮。”`,`"Next morning the whole town showed up in pickups with chainsaws. Nobody asked if we needed help."`,`«Na manhã seguinte a vila inteira apareceu de carrinha e motosserra. Ninguém perguntou se precisávamos de ajuda.»`)],[
  {t:t(`帮她修被野猪拱倒的篱笆`,`Help her mend the fence the feral hogs knocked down`,`Ajudá-la a consertar a vedação que os javalis deitaram abaixo`),fx:()=>{addLike('june',2);stat('oficio',2);stat('tex',1);ADV('june','sanmarcos')},next:()=>say(T,t(`铁丝、钳子、汗。干完活她递给你一杯冰羊奶，说你干活像个本地人，“除了骂人用的是外语”。`,`Wire, pliers, sweat. When you're done she hands you a glass of cold goat's milk and says you work like a local, "except you cuss in a foreign language."`,`Arame, alicate, suor. No fim dá-te um copo de leite de cabra frio e diz que trabalhas como um local, «tirando os palavrões serem em língua estrangeira».`),t(`手艺 +2 · 德州味 +1`,`Craft +2 · Texan +1`,`Ofício +2 · Texano +1`))},
  {t:t(`讲外公那条沉了的船`,`Tell her about your grandfather's boat that sank`,`Contar-lhe o barco do teu avô que se afundou`),fx:()=>{addTrust('june',2);stat('saud',2);ADV('june','sanmarcos')},next:()=>say(T,t(`你讲了风暴、若泽、二十多年没人说出口的那句话。琼一直看着那块铁皮。“水退了以后最难的不是重建，”她说，“是不再怪那条河。”`,`You tell her about the storm, about José, about the thing nobody said for twenty-odd years. June keeps her eyes on the tin plate. "After the water goes down, the hard part isn't rebuilding," she says. "It's quitting blaming the river."`,`Contas-lhe a tempestade, o José, a coisa que ninguém disse durante mais de vinte anos. A June não tira os olhos da chapa. «Quando a água baixa, o difícil não é reconstruir», diz. «É deixar de culpar o rio.»`),t(`信任 +2`,`Trust +2`,`Confiança +2`))}]);
 if(s===2)return sc(T,C.wim,[
  t(`你带来一盒用她的蛋做的蛋挞。琼咬了一口，没说话，又咬了一口，然后把剩下的一个藏进了围裙口袋。`,`You've brought a box of custard tarts made with her eggs. June takes a bite, says nothing, takes another, then hides the last one in her apron pocket.`,`Trouxeste uma caixa de pastéis de nata feitos com os ovos dela. A June dá uma dentada, não diz nada, dá outra, e depois esconde o último no bolso do avental.`)],[
  {t:t(`问她愿不愿意每周给你供货`,`Ask if she'd supply you every week`,`Perguntar se te fornece todas as semanas`),req:()=>S.inv.dairy>=2||NEED(t(`库存蛋奶 2（做蛋挞）`,`2 flour/eggs/milk in stock (for the tarts)`,`2 de farinha/ovos/leite em stock (para os pastéis)`)),fx:()=>{S.inv.dairy-=2;addLike('june',2);addTrust('june',1);ADV('june','sanmarcos');S.flags.tx10_juneDone=1},next:()=>{const ok=grantPerk('dairy',0.8,['琼·奥尔布雷克特','June Albrecht','June Albrecht']);return say(T,[t(`“每周四，送奶的车顺路，”她说，“价钱按老客户算。大话王，你赢了。”`,`"Thursdays. The milk run goes your way," she says. "Old-customer price. You win, big talker."`,`«Às quintas. A carrinha do leite passa para os teus lados», diz. «Preço de cliente antigo. Ganhaste, fanfarrão.»`),ok?t(`从此蛋奶进货价永久八折。`,`From now on flour, eggs and milk cost you 20% less, for good.`,`A partir de agora farinha, ovos e leite custam-te menos 20%, para sempre.`):t(`你已经有更便宜的货源了，但她坚持每周捎一篮蛋来，说是“给蛋挞的”。`,`You already have a cheaper source, but she insists on dropping off a basket of eggs each week, "for the tarts".`,`Já tens um fornecedor mais barato, mas ela insiste em deixar um cesto de ovos todas as semanas, «para os pastéis».`)],t(`长期供货：蛋奶 ×0.8`,`Supply deal: dairy ×0.8`,`Acordo: lacticínios ×0.8`))}},
  {t:t(`什么也不问，只说下次再带`,`Ask for nothing; just promise to bring more`,`Não pedir nada; só prometer trazer mais`),fx:()=>{addLike('june',1);stat('charme',1)},next:()=>say(T,t(`她把围裙口袋拍了拍：“这个先欠着。”`,`She pats her apron pocket. "I'll owe you for this one."`,`Bate no bolso do avental. «Este fica a dever.»`))}]);
 return sc(T,C.wim,[pick([t(`琼在给小羊喂奶，头也不抬：“蛋在冷藏箱里，自己拿。”`,`June is bottle-feeding a kid goat and doesn't look up. "Eggs are in the cooler. Help yourself."`,`A June está a dar biberão a um cabrito e nem levanta a cabeça. «Os ovos estão na geleira. Serve-te.»`),t(`琼在谷仓里挂了一张你店的传单，旁边写着：“蛋是我的。”`,`June has pinned your shop's flyer in the barn, with a note beside it: "The eggs are mine."`,`A June afixou o folheto do teu restaurante no celeiro, com uma nota ao lado: «Os ovos são meus.»`)])],[{t:t(`帮她捡一篮蛋`,`Gather a basket of eggs for her`,`Apanhar um cesto de ovos para ela`),fx:()=>{stamp('june');addLike('june',1);stat('tex',1)}}]);
}

/* ---------------- WALT (Luckenbach) ---------------- */
function waltScene(){const s=ST('walt'),T=t(`橡树下的小提琴`,`The fiddle under the oaks`,`O violino debaixo dos carvalhos`);
 if(s===0)return sc(T,C.lb,[
  t(`橡树下围着一圈折叠椅，七八个人轮流起头唱歌，谁会就跟着弹。最老的那个拉小提琴，八十多岁，帽檐压得很低。轮到他时，他拉了一支华尔兹，慢得像在想事情。`,`Under the oaks, a ring of folding chairs: seven or eight people take turns starting a song and whoever knows it joins in. The oldest plays fiddle — past eighty, hat brim pulled low. When his turn comes he plays a waltz, slow as someone thinking.`,`Debaixo dos carvalhos, um círculo de cadeiras dobráveis: sete ou oito pessoas revezam-se a puxar uma canção e quem a sabe acompanha. O mais velho toca violino — mais de oitenta anos, aba do chapéu bem em baixo. Quando chega a vez dele, toca uma valsa, lenta como quem pensa.`),
  t(`散场时他用一句你听不懂的话跟你打招呼，然后换成英语：“我外婆的德语。德州德语。山地里一百多年的老话，我孙子一个字也不会了。”`,`Afterwards he greets you in words you don't understand, then switches to English. "My grandma's German. Texas German. A hundred-odd years old in these hills, and my grandkids don't know a word."`,`No fim cumprimenta-te com palavras que não percebes e depois passa para inglês. «O alemão da minha avó. Alemão do Texas. Mais de cem anos nestas colinas, e os meus netos não sabem uma palavra.»`)],[
  {t:t(`给他哼一段法多`,`Hum him a few bars of fado`,`Cantarolar-lhe uns compassos de fado`),req:()=>S.stats.saud>=35||S.stats.charme>=40||NEED(t(`乡愁 35 或魅力 40`,`Homesickness 35 or Charm 40`,`Saudade 35 ou Charme 40`)),fx:()=>{MEET('walt');addLike('walt',3);stat('saud',2);ADV('walt','luckenbach');log('在卢肯巴赫认识了沃尔特','Met Walt in Luckenbach','Conheceste o Walt em Luckenbach')},next:()=>say(T,t(`他闭着眼听完，拿起琴，把你哼的那几句一模一样拉了一遍，只是慢了一点。“小调，”他说，“全世界离家的人，用的都是小调。”`,`He listens with his eyes shut, then picks up the fiddle and plays your bars back note for note, only a little slower. "Minor key," he says. "Everybody in the world who left home uses the minor key."`,`Ouve de olhos fechados, pega no violino e toca os teus compassos nota por nota, só um pouco mais devagar. «Tom menor», diz. «Toda a gente no mundo que saiu de casa usa o tom menor.»`),t(`认识了沃尔特 · 好感 +3`,`Met Walt · Liking +3`,`Conheceste o Walt · Afeição +3`))},
  {t:t(`告诉他阿尔贝蒂娜太太和那些不会说葡语的老移民`,`Tell him about Dona Albertina and the old immigrants who lost their Portuguese`,`Falar-lhe da Dona Albertina e dos velhos emigrantes que perderam o português`),fx:()=>{MEET('walt');addTrust('walt',2);addLike('walt',1);ADV('walt','luckenbach');log('在卢肯巴赫认识了沃尔特','Met Walt in Luckenbach','Conheceste o Walt em Luckenbach')},next:()=>say(T,t(`“亚速尔人，”他点点头，“跟我们一样。第一代守着，第二代听得懂，第三代只会唱圣诞歌。”他拍拍旁边的空椅子：“下次来，坐这儿。”`,`"Azoreans," he nods. "Same as us. The first generation holds on, the second understands, the third only knows the Christmas songs." He pats the empty chair beside him. "Next time, sit here."`,`«Açorianos», acena. «Como nós. A primeira geração aguenta, a segunda percebe, a terceira só sabe as canções de Natal.» Bate na cadeira vazia ao lado. «Da próxima vez, senta-te aqui.»`),t(`认识了沃尔特 · 信任 +2`,`Met Walt · Trust +2`,`Conheceste o Walt · Confiança +2`))}]);
 if(s===1)return sc(T,C.lb,[
  t(`沃尔特带你去他家，就在溪对面。厨房里，他从铁锅里捞出培根，把油浇在切好的热土豆上，再倒醋、撒洋葱。“我外婆的做法。冷的那种是城里人吃的。”`,`Walt takes you home, just across the creek. In the kitchen he fishes bacon out of an iron skillet and pours the fat over sliced hot potatoes, then vinegar and onion. "Grandma's way. The cold kind is for city folks."`,`O Walt leva-te a casa, logo do outro lado do ribeiro. Na cozinha tira o bacon de uma frigideira de ferro e deita a gordura sobre batatas quentes às rodelas, depois vinagre e cebola. «À maneira da avó. A fria é para gente da cidade.»`)],[
  {t:t(`认真记下做法`,`Write the recipe down carefully`,`Apontar a receita com cuidado`),fx:()=>{learnDish('gpotato');addLike('walt',1);stat('oficio',2);ADV('walt','luckenbach')},next:()=>say(T,t(`醋要热的时候倒，土豆要趁烫。你说葡萄牙人也这样对待土豆：浇橄榄油，要趁烫。他说：“看吧，咱们是亲戚。”`,`The vinegar goes in hot, the potatoes must be scalding. You say the Portuguese treat potatoes the same — olive oil while they're scalding. He says, "See? We're kin."`,`O vinagre entra quente, as batatas a escaldar. Dizes que os portugueses tratam a batata igual — azeite enquanto escalda. Ele diz: «Vês? Somos família.»`),t(`学会新菜：德式热土豆沙拉`,`New dish: German potato salad`,`Prato novo: salada de batata à alemã`))},
  {t:t(`问他外婆的德语还剩多少`,`Ask how much of his grandma's German is left`,`Perguntar quanto resta do alemão da avó`),fx:()=>{learnDish('gpotato');addTrust('walt',2);stat('saud',2);ADV('walt','luckenbach')},next:()=>say(T,t(`他从抽屉里拿出一盘旧磁带，是几十年前大学里的人来录的。“我们这代人一死，就只剩这盘带子了。”临走他把土豆沙拉的做法写在一张纸上给你，用的是英语。`,`He takes an old cassette from a drawer — university people came and recorded it decades ago. "When my generation's gone, this tape is all there'll be." As you leave he writes the potato salad down for you, in English.`,`Tira de uma gaveta uma cassete velha — vieram uns da universidade gravá-la há décadas. «Quando a minha geração morrer, fica só esta cassete.» À saída escreve-te a receita da salada de batata num papel, em inglês.`),t(`学会新菜：德式热土豆沙拉`,`New dish: German potato salad`,`Prato novo: salada de batata à alemã`))}]);
 if(s===2)return sc(T,C.lb,[
  t(`周末，橡树下坐满了人。沃尔特把琴弓指向你：“今天轮到这个葡萄牙小子起头。”所有人都转过来看你。`,`It's the weekend and the circle under the oaks is packed. Walt points his bow at you. "Today this Portuguese boy starts one." Everyone turns to look.`,`Fim de semana, o círculo debaixo dos carvalhos está cheio. O Walt aponta-te o arco. «Hoje é este rapaz português que começa.» Toda a gente se vira para ti.`)],[
  {t:t(`站起来，唱一首完整的法多`,`Stand up and sing a whole fado`,`Levantar-te e cantar um fado inteiro`),req:()=>S.stats.charme>=50||S.stats.saud>=55||NEED(t(`魅力 50 或乡愁 55`,`Charm 50 or Homesickness 55`,`Charme 50 ou Saudade 55`)),fx:()=>{addLike('walt',2);addTrust('walt',2);stat('charme',2);stat('saud',-2);S.cash+=350;S.wk.rev+=350;S.rep+=3;ADV('walt','luckenbach');S.flags.tx10_waltDone=1;if(MET('kyle'))addLike('kyle',1)},next:()=>say(T,[t(`第二段，沃尔特的小提琴悄悄跟了进来，在你的小调下面垫了一层。唱完，没人鼓掌，过了好几秒，才有人说：“再来一首。”`,`On the second verse Walt's fiddle slips in, laying a floor under your minor key. When you finish nobody claps; a few seconds pass before someone says, "Another one."`,`Na segunda estrofe o violino do Walt entra devagar, a pôr um chão por baixo do teu tom menor. Quando acabas ninguém aplaude; passam uns segundos até alguém dizer: «Mais uma.»`),t(`沃尔特替你接下了舞厅一年一度德裔传统晚宴的外烩：“三百五十块，土豆沙拉你来做。”${MET('kyle')?'他还说，让那个叫凯尔的小子来找他学两手。':''}`,`Walt hands you the catering for the dance hall's yearly German heritage supper: "Three-fifty, and you make the potato salad."${MET('kyle')?' He adds that the boy called Kyle should come learn a thing or two from him.':''}`,`O Walt passa-te o catering do jantar anual da herança alemã no salão de baile: «Trezentos e cinquenta, e a salada de batata fazes tu.»${MET('kyle')?' E diz que o rapaz chamado Kyle devia vir aprender umas coisas com ele.':''}`)],t(`外烩 +$350 · 口碑 +3`,`Catering +$350 · Reputation +3`,`Catering +$350 · Reputação +3`))},
  {t:t(`起一首大家都会的老歌，让他们唱`,`Start an old song everyone knows and let them carry it`,`Puxar uma canção antiga que toda a gente sabe e deixá-los cantar`),fx:()=>{addLike('walt',1);stat('tex',2);S.rep+=1;ADV('walt','luckenbach');S.flags.tx10_waltDone=1},next:()=>say(T,t(`就是那首让这个小村出名的七十年代老歌。你只会副歌，但副歌就够了，二十个人替你唱完了剩下的。沃尔特笑着摇头：“下次唱你自己的。”`,`It's the seventies song that made this little place famous. You only know the chorus, but the chorus is enough — twenty people sing the rest for you. Walt shakes his head, grinning. "Next time sing your own."`,`É a canção dos anos setenta que tornou esta terrinha famosa. Só sabes o refrão, mas chega — vinte pessoas cantam o resto por ti. O Walt abana a cabeça a sorrir. «Da próxima canta uma tua.»`),t(`德州味 +2`,`Texan +2`,`Texano +2`))}]);
 return sc(T,C.lb,[pick([t(`沃尔特给你留着旁边那把椅子。`,`Walt has kept the chair beside him for you.`,`O Walt guardou-te a cadeira ao lado.`),t(`沃尔特拉了一支你没听过的华尔兹，说是昨晚梦见他外婆哼的。`,`Walt plays a waltz you've never heard; he says his grandma hummed it in a dream last night.`,`O Walt toca uma valsa que nunca ouviste; diz que a avó lha cantarolou num sonho esta noite.`)])],[{t:t(`坐下听`,`Sit and listen`,`Sentar e ouvir`),fx:()=>{stamp('walt');addLike('walt',1);stat('saud',-1);stat('tex',1)}}]);
}

/* ================= CITIES ================= */
Object.assign(CITIES,{
 sanmarcos:{
  n:t(`圣马科斯与温伯利`,`San Marcos & Wimberley`,`San Marcos e Wimberley`), region:'hill', miles:85, trip:'day', hotel:95, via:['i35'],
  desc:t(`清得能数沙粒的圣马科斯河从两百多个泉眼里涌出来；往西二十分钟山路，是温伯利的柏树溪。`,`The San Marcos River, clear enough to count the sand grains, wells up from two hundred-odd springs; twenty minutes west through the hills is Wimberley's Cypress Creek.`,`O rio San Marcos, tão límpido que se contam os grãos de areia, nasce de duzentas e tal nascentes; vinte minutos a oeste, pelas colinas, fica o Cypress Creek de Wimberley.`),
  arrive:()=>[inSeason(1,12)?t(`夏天的圣马科斯：河上漂满了坐在黑色内胎里的大学生，冷藏箱也坐着内胎跟在后面。`,`San Marcos in summer: the river is covered with college kids floating in black inner tubes, their coolers riding tubes of their own behind them.`,`San Marcos no verão: o rio está coberto de universitários a boiar em câmaras-de-ar pretas, com as geleiras atrás em câmaras-de-ar próprias.`):t(`从州际公路下来，一转弯就是河。水是绿玻璃的颜色，冬天也冒着一点白气。`,`Off the interstate, one turn and there's the river — green-glass water, breathing a little steam even in the cold months.`,`Saindo da autoestrada, uma curva e aí está o rio — água cor de vidro verde, a fumegar um pouco mesmo nos meses frios.`)],
  locs:[
   {id:'tx10_springlake', n:t(`春湖：河的源头`,`Spring Lake, the headwaters`,`Spring Lake, a nascente`), acts:[
    {id:'boat', n:t(`坐玻璃底船`,`Ride a glass-bottom boat`,`Andar no barco de fundo de vidro`), cost:1, req:daily('boat'), tip:t(`看泉眼在湖底“沸腾”`,`Watch the springs "boil" on the lake bed`,`Ver as nascentes a «ferver» no fundo`),
     run:()=>{stamp('boat');const w=W();return sc(t(`玻璃底船`,`The glass-bottom boat`,`O barco de fundo de vidro`),C.sm,[
      t(`船底是一块玻璃。下面，白沙一小团一小团地往上翻，像一锅刚开的水——那是泉眼。导游说，人们常说这一带一万多年前就有人住，是北美住人最久的地方之一。`,`The bottom of the boat is glass. Below, white sand churns up in little puffs like a pot just coming to the boil — those are the springs. The guide says people often call this one of the longest continuously inhabited places in North America, over ten thousand years.`,`O fundo do barco é de vidro. Lá em baixo a areia branca revolve-se em pequenos sopros, como uma panela a começar a ferver — são as nascentes. O guia diz que se costuma dizer que este é um dos sítios habitados há mais tempo na América do Norte, há mais de dez mil anos.`),
      ...(w?[t(`${SH(w)}趴在玻璃上找蝾螈，鼻子压得扁扁的。`,`${SH(w)} lies flat on the glass hunting for salamanders, nose squashed against it.`,`${SH(w)} deita-se em cima do vidro à procura de salamandras, com o nariz esmagado.`)]:[])],[
      {t:t(`想起里斯本水族馆的大玻璃`,`Think of the big tank at the Lisbon Oceanarium`,`Pensar no grande tanque do Oceanário`),fx:()=>{stat('saud',2);if(w)addLike(w,1)}},
      {t:t(`问导游这水最后流到哪里`,`Ask the guide where the water ends up`,`Perguntar ao guia onde vai parar a água`),fx:()=>{stat('tex',2);stat('oficio',1);if(w)addLike(w,1)},next:()=>say(t(`河的去向`,`Where the river goes`,`Para onde vai o rio`),t(`汇进瓜达卢佩河，再流进墨西哥湾。“你在这里看到的每一滴，几天以后就在海里了。”你想，那也算离里斯本近了一点。`,`Into the Guadalupe, then into the Gulf of Mexico. "Every drop you see here is in the sea a few days from now." You figure that puts it a little nearer Lisbon.`,`Para o Guadalupe e depois para o Golfo do México. «Cada gota que vês aqui está no mar daqui a uns dias.» Pensas que isso a põe um pouco mais perto de Lisboa.`))}])}},
    {id:'fe', n:t(`找护河的菲老师`,`Look for Miss Fe the river keeper`,`Procurar a professora Fe`), cost:2, req:STAGE('ofelia','sanmarcos',3), tip:t(`三次来访的故事`,`A story over three visits`,`Uma história em três visitas`), run:()=>feScene()}
   ]},
   {id:'tx10_river', n:t(`河边公园`,`The riverside parks`,`Os parques junto ao rio`), acts:[
    {id:'float', n:t(`坐内胎漂流`,`Float the river in a tube`,`Descer o rio numa câmara-de-ar`), cost:2, req:SEAS(1,12,`只在夏天（第 1–12 周）`,`Summer only (weeks 1–12)`,`Só no verão (semanas 1–12)`), tip:t(`夏天的德州传统`,`A Texas summer ritual`,`Um ritual de verão no Texas`),
     run:()=>sc(t(`漂流`,`Tubing`,`Câmara-de-ar`),C.sm,[t(`你租了一只黑内胎，屁股一沉就被河带走了。头顶是柏树和山核桃树，旁边一群学生把冷藏箱绑在一起，组成了一支舰队，问你要不要入伙。`,`You rent a black tube, drop in, and the river takes you. Overhead, cypress and pecan; beside you, a pack of students have lashed their coolers together into a fleet and ask if you want to join.`,`Alugas uma câmara-de-ar preta, sentas-te e o rio leva-te. Por cima, ciprestes e nogueiras-pecã; ao lado, um bando de estudantes amarrou as geleiras umas às outras numa frota e pergunta se queres entrar.`)],[
      {t:t(`入伙，给他们讲里斯本的夜`,`Join up and tell them about Lisbon nights`,`Entrar e contar-lhes as noites de Lisboa`),fx:()=>{stat('charme',2);stat('tex',1);S.rep+=1},next:()=>say(t(`舰队`,`The fleet`,`A frota`),t(`漂到下游时，舰队里有六个人存了你店的地址，两个人说秋天要去里斯本。`,`By the time you reach the take-out, six of the fleet have saved your shop's address and two swear they're going to Lisbon in the fall.`,`Quando chegam à saída, seis da frota guardaram a morada do restaurante e dois juram que vão a Lisboa no outono.`),t(`魅力 +2 · 口碑 +1`,`Charm +2 · Reputation +1`,`Charme +2 · Reputação +1`))},
      {t:t(`一个人漂，什么也不想`,`Float alone and think of nothing`,`Boiar sozinho sem pensar em nada`),fx:()=>{S.energy=Math.min(10,S.energy+2);stat('saud',-1)}}])},
    {id:'popup', n:t(`河边快闪摊`,`Riverside pop-up stall`,`Banca pop-up junto ao rio`), cost:2, req:daily('smpop'), tip:t(`从库存卖出；夏天游客多`,`Sells from your stock; busier in summer`,`Vende do teu stock; mais gente no verão`),
     run:()=>{stamp('smpop');return pop(t(`河边快闪摊`,`Riverside pop-up`,`Banca junto ao rio`),inSeason(1,12)?14:8,inSeason(1,12)?1.3:1.05,`从水里爬上来的人什么都吃。一个湿漉漉的男孩连吃三个猪排包，问你是不是从“葡萄牙县”来的。`,`People climbing out of the river will eat anything. A dripping boy eats three bifanas in a row and asks if you're from "Portugal County."`,`Quem sai do rio come tudo. Um rapaz a pingar come três bifanas seguidas e pergunta se vens do «condado de Portugal».`)}}
   ]},
   {id:'tx10_txstate', n:t(`德州州立大学`,`Texas State University`,`Universidade Estadual do Texas`), acts:[
    {id:'oldmain', n:t(`爬上山坡看老主楼`,`Climb the hill to Old Main`,`Subir a colina até ao Old Main`), cost:1, req:daily('oldmain'), tip:t(`红屋顶的老楼，一位总统的母校`,`A red-roofed old hall; a president's alma mater`,`Um edifício de telhado vermelho; a escola de um presidente`),
     run:()=>{stamp('oldmain');return sc(t(`老主楼`,`Old Main`,`Old Main`),C.sm,[t(`山坡顶上，老主楼的红屋顶和尖塔像一座小城堡。林登·约翰逊年轻时在这里念师范，毕业前去南德州一个小镇教过墨西哥裔穷孩子——后来他当了总统，签了好几部民权和教育法案。`,`At the top of the hill Old Main's red roofs and spires look like a small castle. Lyndon Johnson trained as a teacher here, and before graduating taught poor Mexican American kids in a small South Texas town — later, as president, he signed a string of civil-rights and education laws.`,`No alto da colina, os telhados vermelhos e as torres do Old Main parecem um pequeno castelo. Lyndon Johnson estudou aqui para professor e, antes de acabar o curso, deu aulas a crianças pobres mexicano-americanas numa vila do sul do Texas — mais tarde, como presidente, assinou uma série de leis de direitos civis e educação.`)],[
      {t:t(`坐在草坪上看学生来来往往`,`Sit on the lawn and watch the students go by`,`Sentar na relva a ver os estudantes passar`),fx:()=>{stat('saud',1);stat('charme',1)},next:()=>say(t(`草坪`,`The lawn`,`A relva`),t(`你想起自己没读完的建筑系。也许不是没读完，只是换了一间教室。`,`You think of the architecture degree you never finished. Maybe you didn't quit — you just changed classrooms.`,`Pensas no curso de arquitetura que não acabaste. Se calhar não desististe — só mudaste de sala de aula.`))},
      {t:t(`在学生活动中心贴你店的传单`,`Pin your flyer up at the student center`,`Afixar o teu folheto no centro de estudantes`),fx:()=>{S.rep+=1;ONL(2)},next:()=>say(t(`传单`,`Flyer`,`Folheto`),t(`公告栏上一半是找室友，一半是丢狗。你的传单夹在中间：“葡萄牙烧烤，离这儿一个小时，值得。”`,`Half the board is roommate wanted, half is lost dog. Your flyer sits between: "Portuguese grill, an hour away, worth it."`,`Metade do quadro é procura de colega de casa, metade cão perdido. O teu folheto fica no meio: «Churrasco português, a uma hora daqui, vale a pena.»`),t(`线上评分 +2`,`Rating +2`,`Avaliação +2`))}])}},
    {id:'cookoff', n:t(`学生会慈善烤肉赛`,`Student charity cook-off`,`Concurso de churrasco solidário`), cost:3, req:daily('smcook'), tip:t(`烤架小游戏，名次决定奖金`,`Grill mini-game; placing decides the prize`,`Minijogo da grelha; a classificação decide o prémio`),
     run:()=>{stamp('smcook');return cityGrill(q=>{const w=W();const prize=q>=1.25?400:q>=1.05?200:q>=0.9?80:0;S.cash+=prize;S.wk.rev+=prize;if(prize)S.rep+=2;if(q>=1.25)ONL(3);
      return say(t(`慈善烤肉赛`,`Charity cook-off`,`Concurso solidário`),[q>=1.25?t(`评委是三个兄弟会男生和一位化学系教授。教授吃完你的肉，在评分表上写了一个化学式，旁边画了一颗星。第一名。`,`The judges are three fraternity boys and a chemistry professor. The professor finishes your meat and writes a chemical formula on the score sheet, with a star beside it. First place.`,`Os jurados são três rapazes de uma fraternidade e um professor de química. O professor acaba a tua carne e escreve uma fórmula química na folha, com uma estrela ao lado. Primeiro lugar.`):q>=1.05?t(`第二名，输给了一个从小在洛克哈特长大的工程系女生。她过来跟你握手：“下次见。”`,`Second, behind an engineering student who grew up in Lockhart. She comes over to shake your hand. "See you next time."`,`Segundo, atrás de uma estudante de engenharia que cresceu em Lockhart. Vem apertar-te a mão. «Até à próxima.»`):t(`肉烤得一般。但你的烟熏味把半个校园都招来了，募捐箱满了。`,`The meat's so-so. But your smoke draws half the campus over and the donation box fills up.`,`A carne fica assim-assim. Mas o teu fumo atrai meio campus e a caixa de donativos enche.`),...(w?[t(`${SH(w)}在旁边当你的“经纪人”，替你跟评委套近乎。`,`${SH(w)} plays your "agent", buttering up the judges.`,`${SH(w)} faz de teu «agente», a lisonjear os jurados.`)]:[])],prize?t(`奖金 +$${prize}`,`Prize +$${prize}`,`Prémio +$${prize}`):t(`没有奖金`,`No prize`,`Sem prémio`))})}}
   ]},
   {id:'tx10_wimberley', n:t(`温伯利与柏树溪`,`Wimberley & Cypress Creek`,`Wimberley e Cypress Creek`), acts:[
    {id:'bluehole', n:t(`蓝洞与雅各布井`,`Blue Hole & Jacob's Well`,`Blue Hole e Jacob's Well`), cost:2, req:daily('bluehole'), tip:t(`柏树下的泳池和一口通往地下的泉`,`A swimming hole under cypresses and a spring that drops into the earth`,`Uma piscina natural sob ciprestes e uma nascente que desce para a terra`),
     run:()=>{stamp('bluehole');const w=W();const sum=inSeason(1,12);return sc(t(`蓝洞`,`Blue Hole`,`Blue Hole`),C.wim,[
      sum?t(`柏树溪在这里拐了个弯，积成一潭绿水。老柏树的根像手指一样伸进水里，树枝上挂着荡绳，孩子们一个接一个尖叫着跳下去。`,`Cypress Creek bends here into a pool of green water. Old cypress roots reach into it like fingers; rope swings hang from the branches and kids drop in one after another, shrieking.`,`O Cypress Creek dá aqui uma curva e forma um poço de água verde. As raízes dos ciprestes velhos entram na água como dedos; há cordas penduradas nos ramos e os miúdos atiram-se um atrás do outro, aos gritos.`):t(`不是游泳的季节，蓝洞边只有落羽杉的红褐色针叶，一片一片漂在水面上。`,`It's not swimming season; at Blue Hole there are only the rust-brown cypress needles drifting one by one on the water.`,`Não é época de banhos; no Blue Hole só há agulhas castanho-avermelhadas dos ciprestes a flutuar uma a uma.`),
      t(`上游不远是雅各布井：溪床上一个圆圆的深洞，泉水从地底涌出来，往下看是一条看不到底的蓝色隧道。`,`A little upstream is Jacob's Well: a round hole in the creek bed where spring water wells up from the earth — look down and it's a blue tunnel with no visible bottom.`,`Um pouco acima fica o Jacob's Well: um buraco redondo no leito do ribeiro onde a água brota da terra — olhas para baixo e é um túnel azul sem fundo à vista.`)],[
      sum?{t:w?t(`拉着${SH(w)}一起荡绳跳下去`,`Grab ${SH(w)} and take the rope swing together`,`Agarrar ${SH(w)} e saltarem juntos da corda`):t(`荡绳跳下去`,`Take the rope swing`,`Saltar da corda`),fx:()=>{stat('tex',2);stat('saud',-1);if(w)addLike(w,2)},next:()=>say(t(`扑通`,`Splash`,`Splash`),w?t(`你们一起砸进水里，冒出来的时候${SH(w)}笑得呛了水，抓着你的胳膊不放。`,`You hit the water together; ${SH(w)} comes up laughing, choking on water, and won't let go of your arm.`,`Caem juntos na água; ${SH(w)} vem à tona a rir, engasgado, e não te larga o braço.`):t(`水冷得你在空中就后悔了。上来以后，一个十岁的孩子给你打了八分。`,`The water's so cold you regret it in midair. When you climb out a ten-year-old gives you an eight.`,`A água está tão fria que te arrependes ainda no ar. Quando sais, um miúdo de dez anos dá-te um oito.`))}:{t:t(`在落叶上坐一会儿`,`Sit a while on the fallen needles`,`Sentar um bocado nas agulhas caídas`),fx:()=>{stat('saud',-1);if(w)addLike(w,1);S.energy=Math.min(10,S.energy+1)}},
      {t:t(`在雅各布井边看那口蓝洞很久`,`Stand over Jacob's Well and stare into the blue`,`Ficar muito tempo a olhar para o azul do Jacob's Well`),fx:()=>{stat('saud',2);stat('oficio',1)},next:()=>say(t(`雅各布井`,`Jacob's Well`,`Jacob's Well`),t(`你想，若泽的秘密也是这样：表面一个小洞，下面是一整条你看不见的路。`,`You think José's secrets are like this: a small hole on the surface, a whole hidden road beneath.`,`Pensas que os segredos do José são assim: um buraquinho à superfície e uma estrada inteira escondida por baixo.`))}])}},
    {id:'june', n:t(`找卖鸡蛋的琼`,`Find June the egg seller`,`Procurar a June dos ovos`), cost:2, req:STAGE('june','sanmarcos',3), tip:t(`三次来访的故事 · 长期供货`,`A story over three visits · supply deal`,`Uma história em três visitas · acordo de fornecimento`), run:()=>juneScene()}
   ]}
  ]
 },
 luckenbach:{
  n:t(`卢肯巴赫`,`Luckenbach`,`Luckenbach`), region:'hill', miles:115, trip:'day', hotel:120, via:['i35','us290'],
  desc:t(`地图上几乎找不到的山地小村：一座老邮局兼杂货铺、一座木头舞厅，和一圈在橡树下抱着吉他的人。`,`A Hill Country hamlet you can barely find on a map: an old post office and general store, a wooden dance hall, and a ring of people with guitars under the oaks.`,`Uma aldeola do Hill Country que mal se encontra no mapa: um velho correio e mercearia, um salão de baile de madeira e um círculo de gente de guitarra debaixo dos carvalhos.`),
  arrive:()=>[inSeason(38,44)?t(`从290 号国道拐进小路，两边的田里开满了蓝帽花和红色的印第安画笔花。`,`Off US-290 onto the back road, the fields on both sides are full of bluebonnets and red Indian paintbrush.`,`Saindo da US-290 para a estrada secundária, os campos dos dois lados estão cheios de tremoceiros azuis e de castilejas vermelhas.`):t(`路牌上写着村名，下面没有人口数。有人告诉你，七十年代一位爱开玩笑的牧场主把整个村子买了下来，从此这里的规矩是：人人都是个人物。`,`The road sign gives the name and no population. Someone tells you that in the seventies a joker of a rancher bought the whole town, and ever since the rule here has been: everybody's somebody.`,`A placa tem o nome e nenhuma população. Alguém te conta que nos anos setenta um rancheiro brincalhão comprou a terra inteira e, desde então, a regra aqui é: toda a gente é alguém.`)],
  locs:[
   {id:'tx10_store', n:t(`老邮局兼杂货铺`,`The old post office & general store`,`O velho correio e mercearia`), acts:[
    {id:'postcard', n:t(`寄一张盖本村邮戳的明信片`,`Mail a postcard with the village postmark`,`Mandar um postal com o carimbo da aldeia`), cost:1, req:daily('postcard'), tip:t(`十九世纪德国移民留下的老铺子`,`A store left by nineteenth-century German settlers`,`Uma loja deixada pelos colonos alemães do século XIX`),
     run:()=>{stamp('postcard');return sc(t(`明信片`,`Postcard`,`Postal`),C.lb,[t(`木地板吱呀作响，墙上钉满了几十年来各地访客留下的名片和照片。柜台还是邮局的样子，一排旧木格子信箱。你挑了一张印着村名的明信片。`,`The floorboards creak; the walls are papered with decades of visitors' cards and photos. The counter is still a post office, with a row of old wooden pigeonholes. You pick a postcard with the village name on it.`,`O soalho range; as paredes estão forradas de cartões e fotografias de visitantes de décadas. O balcão ainda é um correio, com uma fila de velhos cacifos de madeira. Escolhes um postal com o nome da aldeia.`)],[
      {t:t(`写给妈妈`,`Write to Mom`,`Escrever à mãe`),fx:()=>{stat('saud',-2);log('从卢肯巴赫给妈妈寄了明信片','Sent Mom a postcard from Luckenbach','Mandaste um postal à mãe de Luckenbach')},next:()=>say(t(`给妈妈`,`To Mom`,`À mãe`),t(`“妈妈：这个村只有三栋房子，可每个人都跟我打招呼。我很好。别担心。”你划掉了“别担心”，又写了一遍。`,`"Mom: this village has three buildings and everyone says hello to me. I'm fine. Don't worry." You cross out "don't worry," then write it again.`,`«Mãe: esta aldeia tem três casas e toda a gente me cumprimenta. Estou bem. Não te preocupes.» Riscas «não te preocupes» e voltas a escrevê-lo.`))},
      {t:t(`写给鲁伊，画一顶牛仔帽`,`Write to Rui and draw a cowboy hat`,`Escrever ao Rui e desenhar um chapéu de cowboy`),fx:()=>{stat('tex',1);stat('saud',1)},next:()=>say(t(`给鲁伊`,`To Rui`,`Ao Rui`),t(`“我在一个人人都是人物的地方。所以我也是。你不是。”你笑着贴上邮票。`,`"I'm in a place where everybody's somebody. So I am too. You're not." You stick on the stamp, grinning.`,`«Estou num sítio onde toda a gente é alguém. Portanto eu também sou. Tu não.» Colas o selo a rir.`))}])}},
    {id:'beef', n:t(`跟邻村牧场主买四分之一头牛`,`Buy a quarter of beef from a neighbouring rancher`,`Comprar um quarto de vaca a um rancheiro vizinho`), cost:1, req:daily('lbbeef'), tip:t(`牛肉 8 份，八折`,`8 beef at 80%`,`8 de vaca a 80%`),
     run:()=>{stamp('lbbeef');return buy(t(`四分之一头牛`,`A quarter of beef`,`Um quarto de vaca`),'beef',8,0.8,`杂货铺门口，一个戴旧草帽的牧场主在卖自家吃草长大的牛。他用报纸包好肉，在上面写了你的名字，拼错了，但拼得很认真。`,`Outside the store a rancher in a battered straw hat sells his own grass-fed beef. He wraps it in newspaper and writes your name on it — misspelled, but very carefully.`,`À porta da mercearia, um rancheiro de chapéu de palha gasto vende a carne das vacas que criou a pasto. Embrulha-a em jornal e escreve o teu nome por cima — com erros, mas com muito cuidado.`)}}
   ]},
   {id:'tx10_oaks', n:t(`橡树下的即兴圈`,`The picker circle under the oaks`,`O círculo de músicos debaixo dos carvalhos`), acts:[
    {id:'listen', n:t(`坐在圈外听歌`,`Sit outside the circle and listen`,`Sentar fora do círculo e ouvir`), cost:1, req:daily('listen'), tip:t(`谁会就跟着弹`,`Whoever knows it plays along`,`Quem sabe acompanha`),
     run:()=>{stamp('listen');const w=W();return sc(t(`即兴圈`,`The circle`,`O círculo`),C.lb,[pick([t(`一个穿工装的女孩唱了一首关于她爷爷拖拉机的歌，全场一半人跟着哭。`,`A girl in coveralls sings about her granddad's tractor and half the crowd cries along.`,`Uma rapariga de fato-macaco canta sobre o trator do avô e metade das pessoas chora com ela.`),t(`一个休斯敦来的牙医弹班卓琴，弹得比谁都好，大家假装没注意。`,`A dentist from Houston plays banjo better than anyone and everyone pretends not to notice.`,`Um dentista de Houston toca banjo melhor do que todos e toda a gente finge não reparar.`)]),...(w?[t(`${SH(w)}把头靠在你肩上，跟着打拍子。`,`${SH(w)} leans a head on your shoulder, keeping time.`,`${SH(w)} encosta a cabeça ao teu ombro, a marcar o ritmo.`)]:[])],[
      {t:t(`闭上眼睛听`,`Close your eyes and listen`,`Fechar os olhos e ouvir`),fx:()=>{stat('tex',2);stat('saud',-1);S.energy=Math.min(10,S.energy+1);if(w)addLike(w,2)}},
      {t:t(`借一把吉他，弹你唯一会的和弦`,`Borrow a guitar and play the one chord you know`,`Pedir uma guitarra e tocar o único acorde que sabes`),req:()=>S.stats.charme>=35||NEED(t(`魅力 35`,`Charm 35`,`Charme 35`)),fx:()=>{stat('charme',2);S.rep+=1;if(w)addLike(w,1)},next:()=>say(t(`一个和弦`,`One chord`,`Um acorde`),t(`你把同一个和弦弹了整整三分钟。旁边的人居然围绕着它编出了一首歌。`,`You play the same chord for three solid minutes. The people around you somehow build a whole song on it.`,`Tocas o mesmo acorde durante três minutos inteiros. As pessoas à volta conseguem construir uma canção inteira em cima dele.`))}])}},
    {id:'walt', n:t(`找拉小提琴的沃尔特`,`Find Walt the fiddler`,`Procurar o Walt do violino`), cost:2, req:STAGE('walt','luckenbach',3), tip:t(`三次来访的故事 · 学新菜`,`A story over three visits · new dish`,`Uma história em três visitas · prato novo`), run:()=>waltScene()}
   ]},
   {id:'tx10_hall', n:t(`老舞厅`,`The old dance hall`,`O velho salão de baile`), acts:[
    {id:'dance', n:t(`学跳两步舞`,`Learn the two-step`,`Aprender o two-step`), cost:2, req:daily('dance'), tip:t(`一百多年的木头地板`,`A wooden floor more than a century old`,`Um soalho de madeira com mais de cem anos`),
     run:()=>{stamp('dance');const w=W();return sc(t(`两步舞`,`Two-step`,`Two-step`),C.lb,[t(`舞厅是木板搭的，窗户撑开，风从山上吹进来。地板被一百多年的靴子磨得发亮。快、快、慢——慢，一对对舞伴逆时针绕着场子转。`,`The hall is all boards, windows propped open, wind coming in off the hills. The floor's been polished by more than a century of boots. Quick, quick, slow — slow: couple after couple circles the room counterclockwise.`,`O salão é todo de tábuas, janelas escoradas, vento a entrar das colinas. O soalho foi polido por mais de um século de botas. Rápido, rápido, lento — lento: par atrás de par, à volta da sala ao contrário dos ponteiros.`)],[
      w?{t:t(`和${SH(w)}跳一支`,`Dance one with ${SH(w)}`,`Dançar uma com ${SH(w)}`),fx:()=>{addLike(w,2);stat('tex',2)},next:()=>say(t(`快、快、慢——慢`,`Quick, quick, slow — slow`,`Rápido, rápido, lento — lento`),t(`你踩了${SH(w)}两次脚。第三圈，你们终于跟上了别人，${SH(w)}在你耳边说：“别数了，跟着我。”`,`You step on ${SH(w)}'s feet twice. On the third lap you finally keep up with everyone else, and ${SH(w)} says in your ear: "Stop counting. Follow me."`,`Pisas ${SH(w)} duas vezes. À terceira volta finalmente acompanham os outros, e ${SH(w)} diz-te ao ouvido: «Para de contar. Segue-me.»`))}:{t:t(`请一位老太太教你`,`Ask an old lady to teach you`,`Pedir a uma senhora que te ensine`),fx:()=>{stat('tex',2);stat('charme',1)},next:()=>say(t(`老舞伴`,`An old partner`,`Uma velha parceira`),t(`她七十九岁，在这块地板上跳了六十年。“你的胯太欧洲了，”她说，“放松，想象你刚吃饱。”`,`She's seventy-nine and has danced on these boards for sixty years. "Your hips are too European," she says. "Loosen up. Pretend you just ate."`,`Tem setenta e nove anos e dança nestas tábuas há sessenta. «Tens as ancas demasiado europeias», diz. «Relaxa. Faz de conta que acabaste de comer.»`))},
      {t:t(`坐在长凳上看`,`Sit on the bench and watch`,`Sentar no banco e ver`),fx:()=>{stat('saud',1);stat('tex',1)}}])}},
    {id:'popup', n:t(`舞会外面的烤肉摊`,`Grill stand outside the dance`,`Banca de grelhados à porta do baile`), cost:2, req:AND(()=>S.day>=5||t(`只在周五到周日有舞会`,`Dances only Friday to Sunday`,`Só há baile de sexta a domingo`),daily('lbpop')), tip:t(`从库存卖出，舞客出手大方`,`Sells from your stock; dancers tip well`,`Vende do teu stock; quem dança paga bem`),
     run:()=>{stamp('lbpop');return pop(t(`舞会外面`,`Outside the dance`,`À porta do baile`),12,1.25,`跳累了的人一出门就闻到你的炭火。一位穿珍珠扣衬衫的老先生吃完说：“这比我老婆做的好，别告诉她。”他老婆就站在他后面。`,`Worn-out dancers smell your coals as soon as they step outside. An old gent in a pearl-snap shirt finishes and says, "Better than my wife's — don't tell her." His wife is standing right behind him.`,`Quem sai cansado do baile cheira logo as tuas brasas. Um senhor de camisa de molas nacaradas acaba e diz: «Melhor que a da minha mulher — não lhe digas.» A mulher está mesmo atrás dele.`)}},
    {id:'cookoff', n:t(`秋天的辣肉酱大赛`,`The autumn chili cook-off`,`O concurso de chili do outono`), cost:3, req:AND(SEAS(13,24,`只在秋天（第 13–24 周）`,`Autumn only (weeks 13–24)`,`Só no outono (semanas 13–24)`),daily('lbcook')), tip:t(`烤架小游戏，德州人对辣肉酱很较真`,`Grill mini-game; Texans take chili seriously`,`Minijogo da grelha; os texanos levam o chili a sério`),
     run:()=>{stamp('lbcook');return cityGrill(q=>{const prize=q>=1.25?450:q>=1.05?180:0;S.cash+=prize;S.wk.rev+=prize;stat('tex',2);if(prize)S.rep+=2;
      return say(t(`辣肉酱大赛`,`Chili cook-off`,`Concurso de chili`),[t(`德州人对辣肉酱有一条铁律：不放豆子。你在牛肉里加了一点烟熏辣椒粉和一勺葡萄牙红椒酱，心里很虚。`,`Texans have one iron law about chili: no beans. You add smoked chile and a spoonful of Portuguese red-pepper paste to the beef and feel very unsure.`,`Os texanos têm uma lei de ferro sobre o chili: nada de feijão. Juntas à carne chile fumado e uma colher de massa de pimentão portuguesa e ficas muito inseguro.`),q>=1.25?t(`评委尝了三次，问你那个红色的“秘密武器”是什么。第一名，还被罚了一杯啤酒——因为太好吃。`,`The judges taste it three times and ask what the red "secret weapon" is. First place — and fined a beer for being too good.`,`Os jurados provam três vezes e perguntam qual é a «arma secreta» vermelha. Primeiro lugar — e multado numa cerveja por estar bom demais.`):q>=1.05?t(`第二名。第一名是一位做了四十年辣肉酱的老兵，他特意过来尝了你的，点了点头。`,`Second. First goes to a veteran with forty years of chili behind him; he comes over specially to taste yours, and nods.`,`Segundo. O primeiro é um veterano com quarenta anos de chili; vem de propósito provar o teu e acena.`):t(`没进前三。有个评委说你的辣肉酱“很有异国情调”，不知道是不是夸奖。`,`No placing. One judge calls your chili "real exotic," and you can't tell if it's a compliment.`,`Não ficaste nos três primeiros. Um jurado diz que o teu chili é «muito exótico», e não sabes se é elogio.`)],prize?t(`奖金 +$${prize} · 德州味 +2`,`Prize +$${prize} · Texan +2`,`Prémio +$${prize} · Texano +2`):t(`德州味 +2`,`Texan +2`,`Texano +2`))})}}
   ]}
  ]
 }
});

/* ================= ROADS ================= */
// highway check: use the city's route; older cities without one fall back on region/miles
const FB={
 i35:c=>['central','north','hill'].includes(c.region)||c.miles<=150,
 i10:c=>c.region==='west'&&c.miles>=400,
 i20:c=>(c.region==='west'&&c.miles>=180&&c.miles<400)||(c.region==='north'&&c.miles>=180&&c.miles<=300),
 i45:c=>c.region==='coast'&&c.miles>=170&&c.miles<=240,
 us90:c=>c.region==='west'&&c.miles>=250,
 us290:c=>c.region==='hill',
 i37:c=>c.region==='coast'&&c.miles>=240,
 us281:c=>c.region==='coast'&&c.miles>=330,
 us287:c=>c.region==='north'&&c.miles>=350,
 us59:c=>c.region==='north'&&c.miles>=200&&c.miles<=260,
 us190:c=>c.region==='coast'&&c.miles>=170&&c.miles<=240
};
const HW=(c,k)=>c&&(c.via?c.via.includes(k):!!(FB[k]&&FB[k](c)));
const ANY=(c,...ks)=>ks.some(k=>HW(c,k));
const RM=(c,k)=>t(`路上 · `,`On the road · `,`Na estrada · `)+t(...ROADS[k].n)+` → `+c.n;

/* ---- the Hutchinses: team truckers ---- */
function haulers(c){const s=ST('hutchins'),T=t(`哈钦斯夫妇`,`The Hutchinses`,`Os Hutchins`);
 if(s===0){const k=HW(c,'i10')?'i10':'i20';return sc(T,RM(c,k),[
  t(`半夜的卡车休息站，一排冷藏半挂车嗡嗡地响。柜台前一个灰头发的女人在往保温壶里灌咖啡。“我是达琳，开夜班。我男人朗尼在卧铺里打呼，他开白班。我们一天只在加油的时候见面。”`,`A truck stop at midnight, a row of reefer trailers humming. At the counter a grey-haired woman is filling a thermos. "I'm Darlene. I drive nights. My husband Lonnie's snoring in the sleeper — he drives days. We only see each other at fuel stops."`,`Uma área de serviço para camiões à meia-noite, uma fila de frigoríficos a zumbir. Ao balcão, uma mulher de cabelo grisalho enche um termo. «Sou a Darlene. Conduzo de noite. O meu marido, o Lonnie, está a ressonar no beliche — conduz de dia. Só nos vemos quando metemos gasóleo.»`),
  t(`“结婚二十九年，”她说，“六平方米的驾驶室。秘诀是轮流睡觉。”`,`"Married twenty-nine years," she says. "Six square metres of cab. The secret is taking turns sleeping."`,`«Casados há vinte e nove anos», diz. «Seis metros quadrados de cabine. O segredo é dormir à vez.»`)],[
  {t:t(`送她两个你带的蛋挞`,`Give her two of the custard tarts you brought`,`Dar-lhe dois dos pastéis de nata que trouxeste`),req:()=>S.inv.dairy>=1||NEED(t(`库存蛋奶 1`,`1 flour/eggs/milk in stock`,`1 de farinha/ovos/leite`)),fx:()=>{S.inv.dairy-=1;MEET('hutchins');addLike('hutchins',2);ADV('hutchins');log('在公路上认识了哈钦斯夫妇','Met the Hutchinses on the road','Conheceste os Hutchins na estrada')},next:()=>say(T,t(`“一个给我，一个给那个打呼的。”她把一个用纸巾包好，放进驾驶室，“他醒了会以为是天使送的。”`,`"One for me, one for the snorer." She wraps one in a napkin and sets it in the cab. "He'll wake up thinking an angel left it."`,`«Um para mim, um para o ressonador.» Embrulha um num guardanapo e põe-no na cabine. «Vai acordar a pensar que foi um anjo.»`),t(`认识了哈钦斯夫妇`,`Met the Hutchinses`,`Conheceste os Hutchins`))},
  {t:t(`问她六平方米里怎么不吵架`,`Ask how you don't fight in six square metres`,`Perguntar como não se zangam em seis metros quadrados`),fx:()=>{MEET('hutchins');addTrust('hutchins',1);stat('charme',1);stat('saud',1);ADV('hutchins');log('在公路上认识了哈钦斯夫妇','Met the Hutchinses on the road','Conheceste os Hutchins na estrada')},next:()=>say(T,t(`“吵啊。吵完了还得一起把货送到。”她拧紧保温壶，“货不等人，人就学会不记仇了。”`,`"Oh, we fight. Then we still have to get the load there together." She screws the thermos shut. "Freight won't wait, so you learn not to hold a grudge."`,`«Zangamo-nos, pois. E depois temos de entregar a carga juntos.» Fecha o termo. «A carga não espera, por isso aprende-se a não guardar rancor.»`),t(`认识了哈钦斯夫妇`,`Met the Hutchinses`,`Conheceste os Hutchins`))}]);}
 if(s===1){const k=HW(c,'i45')?'i45':HW(c,'us59')?'us59':'us190';return sc(T,RM(c,k),[
  t(`东边松林里的休息区，你认出了那辆冷藏车。朗尼一个人坐在台阶上，手里捏着一束加油站买的花，已经蔫了。“今天是我们三十周年。达琳想要一顿有桌布的晚饭。装货窗口在夜里两点，我们哪儿也去不了。”`,`At a rest area in the eastern pines you recognise the reefer. Lonnie sits alone on the step holding a gas-station bouquet, already wilting. "Today's our thirtieth. Darlene wanted a dinner with a tablecloth. Our loading window's at two in the morning. We can't go anywhere."`,`Numa área de descanso entre os pinheiros do leste reconheces o frigorífico. O Lonnie está sozinho no degrau com um ramo de flores da bomba de gasolina, já murcho. «Hoje fazemos trinta anos. A Darlene queria um jantar com toalha. A janela de carga é às duas da manhã. Não podemos ir a lado nenhum.»`)],[
  {t:t(`在野餐桌上铺块布，给他们烤一顿`,`Spread a cloth on the picnic table and grill them dinner`,`Estender um pano na mesa de piquenique e grelhar-lhes o jantar`),req:()=>(S.inv.beef>=2||S.inv.pork>=3)||NEED(t(`库存牛肉 2 或猪肉 3`,`2 beef or 3 pork in stock`,`2 de vaca ou 3 de porco em stock`)),fx:()=>{if(S.inv.beef>=2)S.inv.beef-=2;else S.inv.pork-=3;addLike('hutchins',3);addTrust('hutchins',2);stat('oficio',1);ADV('hutchins')},next:()=>say(T,t(`桌布是你车里的一条红格子毯子。达琳从卧铺里出来，看见烛光——其实是手机电筒——捂住了嘴。朗尼说：“我安排的。”达琳说：“你骗人。”然后亲了他。`,`The tablecloth is a red plaid blanket from your car. Darlene comes out of the sleeper, sees the candlelight — really a phone torch — and covers her mouth. Lonnie says, "I arranged it." Darlene says, "Liar." Then she kisses him.`,`A toalha é uma manta aos quadrados vermelhos do teu carro. A Darlene sai do beliche, vê a luz das velas — na verdade a lanterna do telemóvel — e tapa a boca. O Lonnie diz: «Fui eu que organizei.» A Darlene diz: «Mentiroso.» E beija-o.`),t(`好感 +3 · 信任 +2`,`Liking +3 · Trust +2`,`Afeição +3 · Confiança +2`))},
  {t:t(`教朗尼一句葡萄牙情话`,`Teach Lonnie a Portuguese love line`,`Ensinar ao Lonnie uma frase de amor em português`),fx:()=>{addLike('hutchins',2);stat('charme',1);ADV('hutchins')},next:()=>say(T,t(`他练了二十遍，发音像在嚼口香糖。达琳听完愣了三秒，说：“你是不是中风了？”但她一整晚都在笑。`,`He practises twenty times; it sounds like he's chewing gum. Darlene listens, freezes for three seconds and says, "Are you having a stroke?" But she smiles all night.`,`Ele ensaia vinte vezes; parece que está a mascar pastilha. A Darlene ouve, fica parada três segundos e diz: «Estás a ter um AVC?» Mas passa a noite a sorrir.`))}]);}
 const k=HW(c,'i37')?'i37':HW(c,'us281')?'us281':'i35';return sc(T,RM(c,k),[
  t(`南边的平原上，那辆冷藏车在路肩打着双闪等你。朗尼摇下车窗：“我们每周往北拉猪肩肉，35 号州际公路正好路过你们镇。每趟总有半托盘超出订单的，卖不掉就亏了。”`,`On the southern plains the reefer waits on the shoulder, hazards blinking. Lonnie rolls down his window. "We haul pork shoulder north every week, and I-35 runs right past your town. Every trip there's half a pallet over the order. Unsold, it's a loss."`,`Nas planícies do sul o frigorífico espera na berma com os quatro piscas. O Lonnie baixa o vidro. «Levamos pá de porco para norte todas as semanas e a I-35 passa mesmo pela tua vila. Em cada viagem sobra meia palete da encomenda. Se não se vende, é prejuízo.»`),
  t(`达琳探过头来：“还有，有个叫‘孤星砂业’的公司想雇我们夜里拉沙子，现金结账，不开单据。我们没接。觉得你该知道。”`,`Darlene leans across. "And a company called Lone Star Sand wanted to hire us to haul sand at night, cash, no paperwork. We passed. Figured you should know."`,`A Darlene inclina-se. «E uma empresa chamada Lone Star Sand quis contratar-nos para levar areia de noite, a dinheiro, sem papéis. Recusámos. Achámos que devias saber.»`)],[
  {t:t(`握手：多出来的猪肉，按成本卸在你店后门`,`Shake on it: the overflow pork, at cost, at your back door`,`Apertar a mão: o porco a mais, a preço de custo, à tua porta das traseiras`),fx:()=>{addTrust('hutchins',2);ADV('hutchins');S.flags.tx10_haulersDone=1;S.flags.tx10_sandCash=1},next:()=>{const ok=grantPerk('pork',0.8,['哈钦斯夫妇','The Hutchinses','os Hutchins']);return say(T,[t(`“每周二凌晨，”朗尼说，“别把那块空地租给停卡车的，我们要用。”`,`"Tuesdays before dawn," Lonnie says. "Don't rent that empty lot out for truck parking — we'll be using it."`,`«Às terças antes do amanhecer», diz o Lonnie. «Não alugues aquele terreno vazio para estacionar camiões — vamos precisar dele.»`),ok?t(`从此猪肉进货价永久八折。`,`From now on pork costs you 20% less, for good.`,`A partir de agora o porco custa-te menos 20%, para sempre.`):t(`你的猪肉已经很便宜了，但他们每趟还是会在后门放一盒达琳做的饼干。`,`Your pork's already cheap, but every run they still leave a tin of Darlene's cookies at the back door.`,`O teu porco já é barato, mas em cada viagem deixam à porta uma lata de bolachas da Darlene.`)],t(`长期供货：猪肉 ×0.8`,`Supply deal: pork ×0.8`,`Acordo: porco ×0.8`))}},
  {t:t(`先问清楚那家砂业公司的事`,`First ask more about that sand company`,`Primeiro perguntar mais sobre a empresa de areia`),fx:()=>{addTrust('hutchins',1);S.flags.tx10_sandCash=1},next:()=>say(T,t(`“夜里十一点装，凌晨四点前卸，地点在你们镇北边一个老厂子。”达琳说，“猪肉的事，你想好了再告诉我们。”`,`"Load at eleven at night, unload before four in the morning, at an old plant north of your town," Darlene says. "As for the pork — tell us when you've made up your mind."`,`«Carregar às onze da noite, descarregar antes das quatro da manhã, numa fábrica velha a norte da tua vila», diz a Darlene. «Quanto ao porco — diz-nos quando decidires.»`))}]);
}

/* ---- Otis: the old Greyhound driver ---- */
function otisScene(c){const s=ST('otis'),T=t(`灰狗巴士的老司机`,`The old Greyhound driver`,`O velho motorista da Greyhound`);
 if(s===0){const bus=!canDrive();return sc(T,RM(c,'i35'),[
  bus?t(`司机从后视镜里看了你好几次，到了休息站终于开口：“圣鲁伊斯。夏天第一个礼拜，加油站下的车，行李箱少一个轮子。我记得你。”`,`The driver keeps glancing at you in the mirror; at the rest stop he finally speaks. "San Luís. First week of summer, got off at the gas station, suitcase missing a wheel. I remember you."`,`O motorista olha para ti várias vezes pelo espelho; na paragem acaba por falar. «San Luís. Primeira semana do verão, saíste na bomba de gasolina, mala sem uma roda. Lembro-me de ti.»`):t(`休息站里停着一辆灰狗巴士。司机是个瘦高的老头，正在擦后视镜。他看见你，眯起眼：“圣鲁伊斯。夏天第一个礼拜，行李箱少一个轮子。现在你自己开车了？”`,`A Greyhound sits at the rest stop. The driver, a tall, lean old man, is wiping a mirror. He sees you and squints. "San Luís. First week of summer, suitcase missing a wheel. You driving yourself now?"`,`Há um autocarro da Greyhound na área de serviço. O motorista, um velho alto e magro, está a limpar um espelho. Vê-te e semicerra os olhos. «San Luís. Primeira semana do verão, mala sem uma roda. Agora já conduzes?»`),
  t(`他叫奥蒂斯·弗里曼，在这条路上开了三十多年。“我记人不记脸，”他说，“我记箱子。”`,`His name is Otis Freeman, thirty-odd years on this road. "I don't remember faces," he says. "I remember luggage."`,`Chama-se Otis Freeman, mais de trinta anos nesta estrada. «Não me lembro de caras», diz. «Lembro-me de malas.»`)],[
  {t:t(`请他喝杯咖啡`,`Buy him a coffee`,`Pagar-lhe um café`),fx:()=>{MEET('otis');addLike('otis',2);ADV('otis');log('认识了灰狗巴士司机奥蒂斯','Met Otis the Greyhound driver','Conheceste o Otis, motorista da Greyhound')},next:()=>say(T,t(`“不加糖，”他说，“三十年前加，现在医生不让了。”他看了看表：“还有四分钟。下次碰见，我给你讲一只箱子的故事。”`,`"No sugar," he says. "Took it thirty years back. Doctor won't let me now." He checks his watch. "Four minutes. Next time we cross paths I'll tell you about a suitcase."`,`«Sem açúcar», diz. «Há trinta anos punha. Agora o médico não deixa.» Olha para o relógio. «Quatro minutos. Da próxima vez que nos cruzarmos conto-te a história de uma mala.»`),t(`认识了奥蒂斯`,`Met Otis`,`Conheceste o Otis`))},
  {t:t(`问他最喜欢哪一条线`,`Ask which route he loves best`,`Perguntar qual é a linha de que mais gosta`),fx:()=>{MEET('otis');addTrust('otis',1);stat('tex',1);ADV('otis');log('认识了灰狗巴士司机奥蒂斯','Met Otis the Greyhound driver','Conheceste o Otis, motorista da Greyhound')},next:()=>say(T,t(`“往西去的夜车。车里人都睡了，只有我和路。”他笑了，“还有偶尔一个睡不着、盯着窗外的外国小子。”`,`"The night run west. Everyone's asleep, it's just me and the road." He grins. "And now and then some foreign kid who can't sleep, staring out the window."`,`«O noturno para oeste. Toda a gente a dormir, só eu e a estrada.» Sorri. «E de vez em quando um miúdo estrangeiro que não consegue dormir, a olhar pela janela.»`),t(`认识了奥蒂斯`,`Met Otis`,`Conheceste o Otis`))}]);}
 if(s===1){const k=HW(c,'us90')?'us90':HW(c,'i10')?'i10':'i37';return sc(T,RM(c,k),[
  t(`又是奥蒂斯。这回他先开口：“九七年初，我跑科珀斯到韦科那条线。上来一个葡萄牙人，穿水手外套，一身虾船的味道，箱子用绳子捆着。他问我：哪里有工厂，就让我在哪里下。”`,`Otis again. This time he speaks first. "Early '97 I was running Corpus to Waco. A Portuguese fella got on — sailor's coat, smelled like a shrimp boat, suitcase tied with rope. Asked me: wherever there's a factory, let me off there."`,`Outra vez o Otis. Desta vez fala primeiro. «No início de 97 eu fazia Corpus–Waco. Entrou um português — casaco de marinheiro, cheiro a barco de camarão, mala atada com corda. Perguntou-me: onde houver uma fábrica, deixe-me lá.»`),
  t(`“到圣鲁伊斯，罐头厂的烟囱在冒烟。我就停了。下车前他塞给我一个小铁皮的圣像，说是圣安东尼，保佑走远路的人。”他指了指仪表台：那个小圣像还粘在那儿。`,`"At San Luís the cannery stack was smoking. So I stopped. Before he got off he pressed a little tin saint into my hand — Saint Anthony, he said, for folks on long roads." He points at the dashboard: the tiny saint is still stuck there.`,`«Em San Luís a chaminé da fábrica deitava fumo. Parei. Antes de sair meteu-me na mão um santinho de lata — Santo António, disse, para quem anda por longas estradas.» Aponta para o tablier: o santinho ainda lá está colado.`),
  ...(MET('quim')?[t(`虾船的味道——你想起科珀斯的金叔，想起那张“九六年十月”的照片。时间对上了。`,`The shrimp-boat smell — you think of Quim in Corpus, of the photo marked "October '96". The dates line up.`,`O cheiro a barco de camarão — pensas no Quim em Corpus, na foto «outubro de 96». As datas batem certo.`)]:[])],[
  {t:t(`告诉他，那个人是你舅舅`,`Tell him that man was your uncle`,`Dizer-lhe que esse homem era o teu tio`),fx:()=>{addTrust('otis',3);stat('saud',2);ADV('otis')},next:()=>say(T,t(`奥蒂斯沉默了很久，久到休息站的广播又叫了一遍他的车次。“那他在那儿找到了。”他说，“我拉过几万个人，大部分都没找到。”`,`Otis is quiet so long the rest-stop speaker calls his run a second time. "Then he found it there," he says. "I've hauled tens of thousands of folks. Most of 'em never did."`,`O Otis fica calado tanto tempo que o altifalante chama a carreira dele segunda vez. «Então ele encontrou o que procurava lá», diz. «Já levei dezenas de milhares de pessoas. A maioria nunca encontrou.»`),t(`信任 +3`,`Trust +3`,`Confiança +3`))},
  {t:t(`什么也不说，只看那个小圣像`,`Say nothing; just look at the little saint`,`Não dizer nada; só olhar para o santinho`),fx:()=>{addLike('otis',1);stat('saud',3);ADV('otis')},next:()=>say(T,t(`铁皮已经褪色了，圣像怀里的小孩子只剩一个轮廓。你想，若泽到过的地方，比你知道的多得多。`,`The tin has faded; the child in the saint's arms is only an outline now. You think José went to far more places than you know.`,`A lata desbotou; o menino nos braços do santo já é só um contorno. Pensas que o José passou por muitos mais sítios do que sabes.`))}]);}
 const k=HW(c,'us290')?'us290':HW(c,'us287')?'us287':HW(c,'us190')?'us190':'i35';return sc(T,RM(c,k),[
  t(`奥蒂斯在休息站朝你招手，制服熨得笔挺。“下个月我退休。最后一趟，我想让它在一个好地方停一下，让车上的人吃顿热饭。”他看着你，“你那儿就在我的线上。”`,`Otis waves you over at the rest stop, uniform pressed sharp. "I retire next month. Last run, I'd like to stop somewhere good and give the folks aboard a hot meal." He looks at you. "Your place sits right on my line."`,`O Otis acena-te na área de serviço, farda bem engomada. «Reformo-me no mês que vem. Na última viagem quero parar num sítio bom e dar uma refeição quente a quem vai no autocarro.» Olha para ti. «O teu restaurante fica mesmo na minha linha.»`)],[
  {t:t(`答应：整车乘客的午饭你请（$150）`,`Agree: lunch for the whole bus is on you ($150)`,`Aceitar: o almoço do autocarro inteiro fica por tua conta ($150)`),req:MONEY(150),fx:()=>{S.cash-=150;S.wk.spend+=150;addLike('otis',3);addTrust('otis',2);S.rep+=5;ONL(5);ADV('otis');S.flags.tx10_otisDone=1;S.flags.tx10_saint=1;stat('saud',-2)},next:()=>say(T,[t(`那天五十一个乘客挤进你的小店，有个老太太哭了，说她二十年没吃过这么像家里的饭。奥蒂斯在留言簿上写：“最后一站，最好的一站。”`,`That day fifty-one passengers squeeze into your little shop. An old woman cries and says she hasn't had anything this much like home in twenty years. In the guestbook Otis writes: "Last stop, best stop."`,`Nesse dia cinquenta e um passageiros enfiam-se no teu pequeno restaurante. Uma senhora chora e diz que há vinte anos não comia nada tão parecido com casa. No livro de visitas o Otis escreve: «Última paragem, melhor paragem.»`),t(`走之前他把仪表台上的小圣像撬下来，放在你手心里：“该回家了。”你把它摆在若泽的照片旁边。`,`Before he leaves he prises the little saint off the dashboard and sets it in your palm. "Time it went home." You put it beside José's photo.`,`Antes de partir arranca o santinho do tablier e põe-to na palma da mão. «Está na hora de voltar a casa.» Pões-no ao lado da fotografia do José.`)],t(`口碑 +5 · 线上评分 +5 · 得到若泽的圣安东尼小像`,`Reputation +5 · Rating +5 · José's little Saint Anthony`,`Reputação +5 · Avaliação +5 · O santinho de Santo António do José`))},
  {t:t(`说店太小，推荐他去奥斯汀`,`Say the shop's too small; suggest Austin instead`,`Dizer que o restaurante é pequeno demais; sugerir Austin`),fx:()=>{addLike('otis',-1);ADV('otis');S.flags.tx10_otisDone=1},next:()=>say(T,t(`“好吧。”他把帽子戴正，“那就在奥斯汀。”他上车前回头看了你一眼，你觉得自己错过了什么。`,`"All right." He straightens his cap. "Austin, then." He glances back before he climbs aboard, and you feel you've missed something.`,`«Está bem.» Endireita o boné. «Austin, então.» Olha para trás antes de subir e sentes que perdeste qualquer coisa.`))}]);
}

/* ---- Trooper Saldaña ---- */
function gabiScene(c){const s=ST('gabi'),T=t(`公路巡警`,`The trooper`,`A agente`);
 if(s===0){const k=HW(c,'us281')?'us281':HW(c,'i37')?'i37':'us59';return sc(T,RM(c,k),[
  t(`前面一辆运牛的拖车翻在路肩上，几头小牛在牧豆树丛里乱跑。一位女巡警戴着宽檐帽，一边指挥车辆一边对着对讲机喊。太阳像一块烧红的铁。`,`Ahead, a cattle trailer lies on its side on the shoulder and a few calves are running loose in the mesquite. A woman trooper in a wide-brimmed hat directs traffic and shouts into her radio. The sun is like red-hot iron.`,`Mais à frente, um atrelado de gado tombado na berma e uns vitelos à solta entre as algarobeiras. Uma agente de chapéu de abas largas orienta o trânsito e grita para o rádio. O sol parece ferro em brasa.`)],[
  {t:t(`停车，帮她把小牛赶回来`,`Pull over and help her round up the calves`,`Parar e ajudá-la a juntar os vitelos`),req:()=>S.course.ride>=1||S.stats.tex>=30||NEED(t(`骑马课 1 或德州味 30`,`Riding lesson 1 or Texan 30`,`1.ª aula de equitação ou Texano 30`)),fx:()=>{MEET('gabi');addLike('gabi',2);addTrust('gabi',2);stat('tex',2);ADV('gabi');log('认识了公路巡警萨尔达尼亚','Met Trooper Saldaña','Conheceste a agente Saldaña')},next:()=>say(T,t(`你张开胳膊，像露西娅教你的那样慢慢逼过去。二十分钟，最后一头小牛进了临时围栏。她摘下帽子扇风：“加芙列拉·萨尔达尼亚。你不是本地人，但你赶牛像本地人。”`,`Arms wide, you move in slow, the way Lucía taught you. Twenty minutes later the last calf is in the makeshift pen. She takes off her hat and fans herself. "Gabriela Saldaña. You're not from here, but you work cattle like you are."`,`De braços abertos, avanças devagar, como a Lucía te ensinou. Vinte minutos depois o último vitelo está no cercado improvisado. Ela tira o chapéu e abana-se. «Gabriela Saldaña. Não és daqui, mas tratas gado como se fosses.»`),t(`认识了萨尔达尼亚警官 · 信任 +2`,`Met Trooper Saldaña · Trust +2`,`Conheceste a agente Saldaña · Confiança +2`))},
  {t:t(`把车里的冰水全给她和司机`,`Hand all the ice water in your car to her and the driver`,`Dar-lhe a ela e ao condutor toda a água gelada que tens`),fx:()=>{MEET('gabi');addLike('gabi',2);ADV('gabi');log('认识了公路巡警萨尔达尼亚','Met Trooper Saldaña','Conheceste a agente Saldaña')},next:()=>say(T,t(`她一口气喝了半瓶，看了看你的车牌和你的口音，笑了：“葡萄牙？那你一定会做饭。我记住你了。”`,`She drinks half a bottle in one go, takes in your plates and your accent, and smiles. "Portugal? Then you can cook. I'll remember you."`,`Bebe meia garrafa de uma vez, repara na matrícula e no teu sotaque e sorri. «Portugal? Então sabes cozinhar. Vou lembrar-me de ti.»`),t(`认识了萨尔达尼亚警官`,`Met Trooper Saldaña`,`Conheceste a agente Saldaña`))}]);}
 if(s===1){const k=HW(c,'i20')?'i20':HW(c,'us287')?'us287':'i10';return sc(T,RM(c,k),[
  t(`地磅站旁边，萨尔达尼亚警官在检查一排半挂车。她认出你，挥手让你靠边——这回不是罚单。“我爸以前在艾丽斯开塔可店，每个礼拜天凌晨四点起来做烤牛头肉，用龙舌兰叶子包着放进土坑里。店关了，他也走了。我再也没吃到过。”`,`By a weigh station Trooper Saldaña is checking a line of semis. She recognises you and waves you over — not a ticket this time. "My dad ran a taquería in Alice. Every Sunday he got up at four to make barbacoa, wrapped in maguey leaves, down in a pit. The shop closed, then he passed. I've never tasted it since."`,`Junto a uma estação de pesagem a agente Saldaña verifica uma fila de camiões. Reconhece-te e manda-te encostar — desta vez não é multa. «O meu pai tinha uma taqueria em Alice. Todos os domingos levantava-se às quatro para fazer barbacoa, embrulhada em folhas de agave, num buraco na terra. A loja fechou, depois ele morreu. Nunca mais provei.»`)],[
  {t:t(`答应她：用若泽的老烤坑试一次`,`Promise her: you'll try it in José's old pit`,`Prometer-lhe: vais tentar no velho buraco de assar do José`),req:()=>S.stats.oficio>=35||NEED(t(`手艺 35`,`Craft 35`,`Ofício 35`)),fx:()=>{addTrust('gabi',2);addLike('gabi',2);stat('oficio',1);ADV('gabi')},next:()=>say(T,t(`两个礼拜后的一个礼拜天，她穿着便服来了，吃了一口，放下叉子，看着窗外很久。“不一样，”她说，“但方向对了。”`,`Two weeks later, on a Sunday, she comes in plain clothes, takes one bite, sets the fork down and looks out the window a long time. "It's not the same," she says. "But it's headed the right way."`,`Duas semanas depois, num domingo, aparece à paisana, prova, pousa o garfo e fica muito tempo a olhar pela janela. «Não é igual», diz. «Mas vai no caminho certo.»`),t(`信任 +2 · 好感 +2`,`Trust +2 · Liking +2`,`Confiança +2 · Afeição +2`))},
  {t:t(`讲讲你自己的爸爸`,`Tell her about your own father`,`Falar-lhe do teu próprio pai`),fx:()=>{addTrust('gabi',1);stat('saud',2);ADV('gabi')},next:()=>say(T,t(`你没讲多少，她也没问多少。地磅一辆接一辆地响。最后她说：“走吧，限速七十五，别逼我。”`,`You don't say much and she doesn't ask much. The scale clanks truck after truck. Finally she says, "Go on. Limit's seventy-five. Don't make me."`,`Não dizes muito e ela não pergunta muito. A balança bate camião atrás de camião. Por fim diz: «Vai lá. O limite é setenta e cinco. Não me obrigues.»`))}]);}
 return sc(T,RM(c,HW(c,'i35')?'i35':'us190'),[
  t(`夜里，离圣鲁伊斯不远的辅路上，红蓝灯在闪。萨尔达尼亚警官拦下了一辆没有公司名字的翻斗车，车斗里满是沙子，超重一大截，正往老罐头厂那边开。她看见你停下，走过来：“你住这儿。夜里谁在罐头厂那块地上干活？”`,`At night, on the frontage road not far from San Luís, red and blue lights. Trooper Saldaña has pulled over a dump truck with no company name, its bed heaped with sand, way overweight, headed for the old cannery. She sees you stop and walks over. "You live here. Who's working that cannery lot at night?"`,`De noite, na via de serviço perto de San Luís, luzes vermelhas e azuis. A agente Saldaña mandou parar um camião basculante sem nome de empresa, a caixa cheia de areia, com excesso de peso enorme, a caminho da velha fábrica. Vê-te parar e aproxima-se. «Tu moras aqui. Quem é que anda a trabalhar no terreno da fábrica à noite?»`)],[
  {t:t(`告诉她孤星砂业和特拉维斯·博伊德`,`Tell her about Lone Star Sand and Travis Boyd`,`Contar-lhe da Lone Star Sand e do Travis Boyd`),fx:()=>{addTrust('gabi',2);S.flags.tx10_weigh=1;S.flags.tx10_gabiDone=1;S.rep+=3;ONL(3);ADV('gabi');log('萨尔达尼亚警官记下了孤星砂业的超重卡车','Trooper Saldaña logged Lone Star Sand\'s overweight trucks','A agente Saldaña registou os camiões com excesso de peso da Lone Star Sand')},next:()=>say(T,[t(`她在本子上写下那个名字，又写下日期和车重。“超重罚单是公开记录，”她说，“谁想查都能查到。我会一直记，记到有人来问。”`,`She writes the name in her notebook, then the date and the weight. "Overweight citations are public record," she says. "Anybody who wants to look can look. I'll keep writing them till somebody asks."`,`Escreve o nome no bloco, depois a data e o peso. «As multas por excesso de peso são registo público», diz. «Quem quiser ver, vê. Vou continuar a escrevê-las até alguém perguntar.»`),t(`从那以后，礼拜天中午总有两三位巡警来你店里吃饭，坐靠窗的桌子。`,`From then on, every Sunday at noon two or three troopers eat at your shop, at the window table.`,`A partir daí, todos os domingos ao meio-dia dois ou três agentes almoçam no teu restaurante, na mesa da janela.`)],t(`口碑 +3 · 线上评分 +3 · 超重记录成为旁证`,`Reputation +3 · Rating +3 · The weight logs become corroboration`,`Reputação +3 · Avaliação +3 · Os registos de peso servem de prova`))},
  {t:t(`说你不清楚，不想惹麻烦`,`Say you don't know and don't want trouble`,`Dizer que não sabes e não queres problemas`),fx:()=>{addTrust('gabi',-1);S.flags.tx10_gabiDone=1;ADV('gabi')},next:()=>say(T,t(`她看了你一会儿，合上本子。“好吧。麻烦通常不会因为你不想要就不来。”她回到车里，红蓝灯继续闪。`,`She studies you a moment and closes the notebook. "All right. Trouble doesn't usually stay away just because you don't want it." She heads back to her car; the lights keep flashing.`,`Observa-te um momento e fecha o bloco. «Está bem. Os problemas não costumam ficar longe só porque não os queres.» Volta para o carro; as luzes continuam a piscar.`))}]);
}

ROAD_EVENTS.push(
 {id:'tx10_hutchins',cond:c=>{const s=ST('hutchins');return s===0?ANY(c,'i10','i20'):s===1?ANY(c,'i45','us59','us190'):s===2?(ANY(c,'i37','us281')||(HW(c,'i35')&&c.miles>=200)):false},run:c=>haulers(c)},
 {id:'tx10_otis',cond:c=>{const s=ST('otis');return s===0?(HW(c,'i35')&&c.miles>=85):s===1?ANY(c,'us90','i10','i37'):s===2?ANY(c,'us290','us287','us190'):false},run:c=>otisScene(c)},
 {id:'tx10_gabi',cond:c=>{const s=ST('gabi');return s===0?ANY(c,'us281','i37','us59'):s===1?ANY(c,'i20','us287','i10'):s===2?((HW(c,'i35')||HW(c,'us190'))&&c.miles<=150):false},run:c=>gabiScene(c)},

 {id:'tx10_i35deck',cond:c=>HW(c,'i35')&&c.miles>=85&&c.region!=='north'&&!ANY(c,'i20','i35e','us287'),run:c=>sc(t(`双层的州际公路`,`The double-decker interstate`,`A autoestrada de dois andares`),RM(c,'i35'),[t(`穿过奥斯汀市中心时，35 号州际公路分成了上下两层。上层能看见州议会大厦的圆顶和河上的桥；下层像一条长长的水泥隧道。你永远选不对该走哪一层。`,`Through downtown Austin, I-35 splits into two decks. Up top you can see the Capitol dome and the bridges over the river; below is a long concrete tunnel. You never pick the right one.`,`No centro de Austin a I-35 divide-se em dois andares. Em cima vê-se a cúpula do Capitólio e as pontes sobre o rio; em baixo é um longo túnel de betão. Nunca escolhes o certo.`)],[
  {t:t(`走上层，看一眼议会大厦`,`Take the upper deck for a glimpse of the Capitol`,`Ir por cima para ver o Capitólio`),fx:()=>{stat('tex',1);stat('charme',1)}},
  {t:t(`走下层，跟着收音机唱`,`Take the lower deck and sing with the radio`,`Ir por baixo a cantar com o rádio`),fx:()=>{stat('saud',-1);S.energy=Math.min(10,S.energy+1)}}])},
 {id:'tx10_i10check',cond:c=>HW(c,'i10')&&c.region==='west',run:c=>{const ok=S.flags.visa||S.flags.green;return sc(t(`边境检查站`,`The Border Patrol checkpoint`,`O posto de controlo da fronteira`),RM(c,'i10'),[t(`10 号州际公路西段直得像用尺子画的，两个小时不用转方向盘。然后，离边境还很远的地方，所有车都慢下来：边境巡逻队的检查站，橙色锥筒，一条狗在车与车之间嗅来嗅去。`,`The western stretch of I-10 is ruler-straight; you don't touch the wheel for two hours. Then, still far from the border, everything slows: a Border Patrol checkpoint, orange cones, a dog sniffing from car to car.`,`O troço ocidental da I-10 é a direito como uma régua; não mexes no volante durante duas horas. Depois, ainda longe da fronteira, tudo abranda: um posto da Patrulha da Fronteira, cones laranja, um cão a farejar de carro em carro.`),t(`“美国公民吗？”你摇头，递上护照。${ok?'签证页没问题。':''}他翻得很慢。`,`"US citizen?" You shake your head and hand over your passport.${ok?' The visa page is in order.':''} He turns the pages slowly.`,`«Cidadão americano?» Abanas a cabeça e entregas o passaporte.${ok?' A página do visto está em ordem.':''} Ele folheia devagar.`)],[
  {t:t(`安静地等，回答简短`,`Wait quietly and keep your answers short`,`Esperar calmamente e responder curto`),fx:()=>{stat('tex',1)},next:()=>say(t(`放行`,`Waved through`,`Pode seguir`),t(`“去哪儿？”“去做生意。”他把护照还给你：“一路平安。”你开出去一英里才发现自己一直屏着气。`,`"Where to?" "Business." He hands back the passport. "Drive safe." A mile on, you realise you've been holding your breath.`,`«Para onde?» «Negócios.» Devolve o passaporte. «Boa viagem.» Uma milha à frente percebes que estiveste a suster a respiração.`))},
  {t:t(`跟他聊两句那条狗`,`Chat with him about the dog`,`Falar-lhe do cão`),req:()=>S.accent!=='浓'||t(`口音太重，最好少说话`,`Accent's too thick — better say little`,`Sotaque forte demais — melhor falar pouco`),fx:()=>{stat('charme',1);stat('saud',1)},next:()=>say(t(`那条狗`,`The dog`,`O cão`),t(`狗叫雷吉，八岁，快退休了。“比我们大部分人都能干，”他说，“就是不会填表。”`,`The dog's called Reggie, eight years old, nearly retired. "Better at the job than most of us," he says. "Just can't do paperwork."`,`O cão chama-se Reggie, oito anos, quase reformado. «Faz o trabalho melhor do que a maioria de nós», diz. «Só não sabe preencher papéis.»`))}])}},
 {id:'tx10_i10swamp',cond:c=>HW(c,'i10')&&c.region!=='west',run:c=>sc(t(`沼泽上的长桥`,`The long bridge over the swamp`,`A ponte comprida sobre o pântano`),RM(c,'i10'),[t(`过了休斯敦往东，10 号州际公路架在三一河的低地上，一座接一座的长桥。桥下是落羽杉、黑水和白鹭。远处炼油厂的火炬在白天也亮着。`,`East of Houston, I-10 rides over the Trinity River bottoms on one long bridge after another. Below: bald cypress, black water, egrets. In the distance a refinery flare burns even by day.`,`A leste de Houston, a I-10 passa sobre as várzeas do rio Trinity em pontes compridas, umas atrás das outras. Por baixo: ciprestes-calvos, água negra, garças. Ao longe, a chama de uma refinaria arde mesmo de dia.`)],[
  {t:t(`数白鹭`,`Count the egrets`,`Contar as garças`),fx:()=>{stat('saud',-1);stat('tex',1)}},
  {t:t(`想起特茹河口的盐田`,`Think of the salt pans on the Tagus estuary`,`Pensar nas salinas do estuário do Tejo`),fx:()=>{stat('saud',2)}}])},
 {id:'tx10_i20dust',cond:c=>HW(c,'i20'),run:c=>sc(t(`沙尘墙`,`The wall of dust`,`A parede de poeira`),RM(c,'i20'),[t(`20 号州际公路两边，一台台抽油机像喝水的铁鸟，一点一点地低头。西边的地平线忽然变成褐色，一堵沙墙压过来，天一下子暗了。`,`Along I-20, pumpjacks nod one after another like iron birds drinking. The western horizon suddenly turns brown and a wall of sand rolls in; the sky goes dark in a moment.`,`Ao longo da I-20, as bombas de petróleo inclinam-se umas atrás das outras como pássaros de ferro a beber. O horizonte a oeste fica castanho de repente e uma parede de areia avança; o céu escurece num instante.`)],[
  {t:t(`开双闪，靠边停，关掉空调外循环`,`Hazards on, pull over, shut the outside air`,`Quatro piscas, encostar, fechar o ar exterior`),fx:()=>{stat('tex',2)},next:()=>say(t(`沙尘`,`Dust`,`Poeira`),t(`二十分钟后沙墙过去了，车变成了土黄色。旁边皮卡上的油田工人朝你竖起拇指：“新人都会往前冲。你没冲。”`,`Twenty minutes later the wall has passed and your car is the colour of dirt. An oilfield hand in the next pickup gives you a thumbs-up. "Greenhorns always try to drive through it. You didn't."`,`Vinte minutos depois a parede passou e o carro está cor de terra. Um trabalhador do petróleo na carrinha ao lado faz-te um polegar para cima. «Os novatos tentam sempre atravessar. Tu não.»`))},
  {t:t(`慢慢往前挪`,`Creep forward slowly`,`Avançar devagar`),fx:()=>{if(Math.random()<0.3){S.cash-=60;S.wk.spend+=60}stat('tex',1)},next:()=>say(t(`沙尘`,`Dust`,`Poeira`),t(`你什么也看不见，只能盯着前车模糊的尾灯。出来以后，挡风玻璃上多了一片细细的划痕。`,`You can see nothing but the blurred tail lights ahead. When you come out, there's a haze of fine scratches on the windshield.`,`Não vês nada além das luzes traseiras desfocadas da frente. Quando sais, o para-brisas tem uma névoa de riscos finos.`))}])},
 {id:'tx10_i45sam',cond:c=>HW(c,'i45'),run:c=>sc(t(`松林里的巨人`,`The giant in the pines`,`O gigante nos pinheiros`),RM(c,'i45'),[t(`45 号州际公路钻进东德州的松林，空气忽然湿了。亨茨维尔附近，树梢上冒出一个白色的巨人：萨姆·休斯顿的雕像，二十多米高，拄着手杖望着公路。再往南，车流越来越密，休斯敦的车潮从六条车道涌过来。`,`I-45 plunges into the East Texas pines and the air turns humid. Near Huntsville a white giant rises over the treetops: the statue of Sam Houston, more than twenty metres tall, leaning on his cane and watching the highway. Further south the traffic thickens until Houston's tide pours in across six lanes.`,`A I-45 mergulha nos pinheiros do leste do Texas e o ar fica húmido. Perto de Huntsville um gigante branco ergue-se acima das copas: a estátua de Sam Houston, com mais de vinte metros, apoiada na bengala a vigiar a estrada. Mais a sul o trânsito adensa-se até a maré de Houston entrar por seis faixas.`)],[
  {t:t(`下高速，在雕像脚下站一会儿`,`Get off and stand at the statue's feet`,`Sair e ficar um bocado aos pés da estátua`),fx:()=>{stat('tex',2);stat('saud',-1)},next:()=>say(t(`萨姆·休斯顿`,`Sam Houston`,`Sam Houston`),t(`牌子上说，他年轻时离家出走，跟切罗基人住过好几年。你想，德州的开国人物也是个离家的人。`,`The plaque says he ran away from home as a young man and lived with the Cherokee for years. Even Texas's founding father, you think, was someone who left home.`,`A placa diz que fugiu de casa em jovem e viveu anos com os Cherokee. Até o pai fundador do Texas, pensas, foi alguém que saiu de casa.`))},
  {t:t(`咬牙挤进休斯敦的车潮`,`Grit your teeth and merge into Houston traffic`,`Cerrar os dentes e entrar no trânsito de Houston`),fx:()=>{stat('tex',1);S.energy=Math.max(0,S.energy-1)},next:()=>say(t(`六条车道`,`Six lanes`,`Seis faixas`),t(`一辆皮卡在你面前连变三条道，没打灯。你学会了休斯敦的第一条规矩：转向灯是给外地人用的。`,`A pickup cuts across three lanes in front of you, no signal. You learn Houston's first rule: turn signals are for out-of-towners.`,`Uma carrinha atravessa três faixas à tua frente, sem pisca. Aprendes a primeira regra de Houston: os piscas são para os de fora.`))}])},
 {id:'tx10_us90train',cond:c=>HW(c,'us90'),run:c=>sc(t(`夜里的火车`,`The night train`,`O comboio da noite`),RM(c,'us90'),[t(`90 号国道往西，过了佩科斯河上那座高高的铁桥，就再没有镇子了。夜里，公路旁边的铁轨上一列货运火车和你并排跑，一百多节车厢，车头的灯照着前面的荒野，汽笛拉得又长又低。`,`West on US-90, past the tall bridge over the Pecos, there are no more towns. At night a freight train runs beside you on the tracks along the highway — over a hundred cars, its headlight on the wilderness ahead, its horn long and low.`,`Na US-90 para oeste, depois da ponte alta sobre o Pecos, acabam as vilas. De noite, um comboio de mercadorias corre ao teu lado na linha ao longo da estrada — mais de cem vagões, o farol na planície deserta, o apito longo e grave.`)],[
  {t:t(`跟火车比一段`,`Race the train for a while`,`Fazer uma corrida com o comboio`),fx:()=>{stat('tex',2)},next:()=>say(t(`并排`,`Side by side`,`Lado a lado`),t(`你们并排开了十几英里。司机拉了两声汽笛，你按了两声喇叭。然后铁轨拐进了山里，你又一个人了。`,`You run side by side for a dozen miles. The engineer blows the horn twice; you honk twice back. Then the tracks bend into the hills and you're alone again.`,`Seguem lado a lado uma dúzia de milhas. O maquinista apita duas vezes; buzinas duas vezes. Depois a linha curva para os montes e voltas a estar sozinho.`))},
  {t:t(`停在路边看星星`,`Stop on the shoulder and look at the stars`,`Parar na berma e olhar as estrelas`),fx:()=>{stat('saud',2);S.energy=Math.min(10,S.energy+1)},next:()=>say(t(`星星`,`Stars`,`Estrelas`),t(`银河从一边地平线跨到另一边。在里斯本你从来没见过这么多星星，那里灯太亮了，人也太多了。`,`The Milky Way runs from one horizon to the other. In Lisbon you never saw this many stars; too many lights, too many people.`,`A Via Láctea vai de um horizonte ao outro. Em Lisboa nunca viste tantas estrelas; demasiadas luzes, demasiada gente.`))}])},
 {id:'tx10_us290peach',cond:c=>HW(c,'us290'),run:c=>{const peach=inSeason(1,10);return sc(peach?t(`路边的桃摊`,`The roadside peach stand`,`A banca de pêssegos à beira da estrada`):t(`公路边的酒庄`,`The wineries by the highway`,`As adegas à beira da estrada`),RM(c,'us290'),[peach?t(`290 号国道穿过山地，路边一个接一个木头小棚，手写的牌子：“今早刚摘的桃子”。整条路都是甜的。`,`US-290 winds through the Hill Country past one wooden shed after another, hand-painted signs: "Peaches picked this morning". The whole road smells sweet.`,`A US-290 atravessa o Hill Country por uns barracões de madeira atrás dos outros, com tabuletas pintadas à mão: «Pêssegos apanhados esta manhã». A estrada inteira cheira a doce.`):t(`290 号国道在弗雷德里克斯堡和约翰逊城之间，两边全是葡萄园和石头砌的酒庄。石灰岩、热天、凉夜——有人说，这里的土跟葡萄牙的杜罗河谷有点像。`,`Between Fredericksburg and Johnson City, US-290 is lined with vineyards and stone-built wineries. Limestone, hot days, cool nights — some say the soil is a little like Portugal's Douro valley.`,`Entre Fredericksburg e Johnson City, a US-290 está ladeada de vinhas e adegas de pedra. Calcário, dias quentes, noites frescas — há quem diga que o solo se parece um pouco com o do Douro.`)],[
  peach?{t:t(`买一箱桃子（$20）`,`Buy a crate of peaches ($20)`,`Comprar uma caixa de pêssegos ($20)`),req:MONEY(20),fx:()=>{S.cash-=20;S.wk.spend+=20;S.rep+=1;stat('tex',1)},next:()=>say(t(`桃子`,`Peaches`,`Pêssegos`),t(`汁顺着手腕流到胳膊肘。回到店里，你把桃子切进蛋挞里，常客们抢光了。`,`Juice runs down your wrist to your elbow. Back at the shop you slice them into custard tarts and the regulars clear them out.`,`O sumo escorre-te do pulso até ao cotovelo. No restaurante cortas os pêssegos para os pastéis de nata e os habituais levam tudo.`))}:{t:t(`进一家酒庄尝一杯`,`Stop at a winery for a glass`,`Parar numa adega e provar um copo`),fx:()=>{stat('saud',-1);stat('oficio',1);stat('charme',1)},next:()=>say(t(`德州的酒`,`Texas wine`,`Vinho do Texas`),t(`你尝出一点熟悉的味道。酿酒师听说你是葡萄牙人，兴奋地说他种了一行国产多瑞加。你没告诉他，这在家乡是再普通不过的葡萄。`,`You taste something familiar. When the winemaker hears you're Portuguese he proudly says he's planted a row of Touriga Nacional. You don't tell him how ordinary that name sounds back home.`,`Sentes um sabor familiar. Quando o enólogo sabe que és português diz, orgulhoso, que plantou uma fila de Touriga Nacional. Não lhe dizes que em casa isso é a coisa mais normal do mundo.`))},
  {t:t(`摇下车窗，闻着开过去`,`Roll down the window and drive through the smell`,`Abrir a janela e passar a sentir o cheiro`),fx:()=>{stat('saud',1)}}])}},
 {id:'tx10_i37wind',cond:c=>HW(c,'i37'),run:c=>sc(t(`海风`,`The sea wind`,`O vento do mar`),RM(c,'i37'),[t(`37 号州际公路往南，过了努埃塞斯河，风变了，带着盐和柴油的味道。远处港口的炼油塔一根根立着，天边一道灰蓝，那是海湾。`,`South on I-37, past the Nueces River, the wind changes: salt and diesel. In the distance the port's refinery towers stand in a row, and along the horizon a grey-blue line — the bay.`,`Na I-37 para sul, depois do rio Nueces, o vento muda: sal e gasóleo. Ao longe as torres das refinarias do porto alinham-se, e no horizonte uma linha azul-acinzentada — a baía.`)],[
  {t:t(`打开车窗，深吸一口`,`Open the window and breathe it in`,`Abrir a janela e respirar fundo`),fx:()=>{stat('saud',3)},next:()=>say(t(`盐`,`Salt`,`Sal`),t(`盐的味道一进鼻子，你就是十岁，站在卡斯凯什的防波堤上，外公在后面喊你别跑。`,`The salt hits your nose and you're ten again, on the Cascais breakwater, your grandfather yelling at you not to run.`,`O cheiro a sal entra-te no nariz e voltas a ter dez anos, no paredão de Cascais, com o avô a gritar-te para não correres.`))},
  {t:t(`关上窗，听渔民电台`,`Shut the window and listen to the fishermen's radio`,`Fechar a janela e ouvir a rádio dos pescadores`),fx:()=>{stat('tex',1);stat('oficio',1)}}])},
 {id:'tx10_us281brush',cond:c=>HW(c,'us281'),run:c=>{const deer=inSeason(13,24);return sc(t(`南部灌木平原`,`The South Texas brush country`,`O mato do sul do Texas`),RM(c,'us281'),[t(`281 号国道往南，地一下子平了，只有牧豆树、仙人掌和铁丝网，几十英里看不见一户人家。`,`South on US-281 the land goes flat: mesquite, prickly pear and barbed wire, mile after mile without a house.`,`Na US-281 para sul a terra fica plana: algarobeiras, figueiras-da-índia e arame farpado, milhas e milhas sem uma casa.`),deer?t(`秋天是猎鹿季，路边的牧场里立着一座座高高的猎台，皮卡后面挂着橙色的背心。`,`It's deer season: tall hunting blinds stand in the pastures, orange vests hang in the backs of pickups.`,`É época de caça ao veado: nas pastagens erguem-se torres de espera altas, coletes cor de laranja pendurados nas carrinhas.`):t(`一只走鹃从路上窜过去，跑得比你想象的快。`,`A roadrunner darts across the road, faster than you'd think.`,`Um corredor-da-estrada atravessa a correr, mais depressa do que imaginavas.`)],[
  {t:t(`在加油站买一袋仙人掌果糖`,`Buy a bag of prickly-pear candy at the gas station`,`Comprar um saco de rebuçados de figo-da-índia na bomba`),fx:()=>{stat('tex',1);S.cash-=4;S.wk.spend+=4}},
  {t:t(`在牧豆树下停车，捡一捆木柴`,`Stop under the mesquite and gather firewood`,`Parar debaixo das algarobeiras e apanhar lenha`),req:()=>canDrive()||t(`坐巴士没法装木柴`,`Can't load firewood on a bus`,`Não dá para levar lenha no autocarro`),fx:()=>{stat('oficio',2);S.rep+=1},next:()=>say(t(`牧豆木`,`Mesquite`,`Algarobeira`),t(`牧豆木烧得烈，烟带一点甜。那个礼拜你的牛胸肉有了一种新的味道，有客人专门问是怎么回事。`,`Mesquite burns hot, with a faintly sweet smoke. That week your brisket has a new note and a customer asks specifically what changed.`,`A algarobeira arde forte, com um fumo levemente doce. Nessa semana o teu peito fumado tem uma nota nova e um cliente pergunta de propósito o que mudou.`))}])}},
 {id:'tx10_us287wind',cond:c=>HW(c,'us287'),run:c=>sc(t(`狭长地带的风车`,`The windmills of the Panhandle`,`Os moinhos do Panhandle`),RM(c,'us287'),[t(`287 号国道斜着往西北爬，进了狭长地带，天变得大得吓人。地平线上一排排白色的风力发电机慢慢转，下面是谷仓塔和老式的铁皮风车——一个抽电，一个抽水。`,`US-287 climbs north-west into the Panhandle and the sky gets frighteningly big. Rows of white wind turbines turn slowly on the horizon; below them, grain elevators and old tin windmills — one pumping power, one pumping water.`,`A US-287 sobe para noroeste até ao Panhandle e o céu fica assustadoramente grande. Filas de turbinas eólicas brancas rodam devagar no horizonte; por baixo, silos de cereal e velhos moinhos de lata — um tira eletricidade, o outro tira água.`)],[
  {t:t(`数风车，数到睡着为止（别开车时）`,`Count turbines till you drift off (not while driving)`,`Contar turbinas até adormecer (sem ser a conduzir)`),fx:()=>{S.energy=Math.min(10,S.energy+1);stat('saud',-1)}},
  {t:t(`想起家乡海边的风车磨坊`,`Think of the old windmills on the hills back home`,`Pensar nos moinhos de vento nas colinas lá de casa`),fx:()=>{stat('saud',2);stat('tex',1)},next:()=>say(t(`风车`,`Windmills`,`Moinhos`),t(`葡萄牙山上的老风车是白的，帆像三角形的手帕。这里的风车大得像教堂，但风是一样的风。`,`Portugal's old hill windmills are white, their sails like triangle handkerchiefs. These are big as churches, but it's the same wind.`,`Os velhos moinhos dos montes portugueses são brancos, com velas como lenços triangulares. Estes são do tamanho de igrejas, mas o vento é o mesmo.`))}])},
 {id:'tx10_us59square',cond:c=>HW(c,'us59'),run:c=>sc(t(`法院广场`,`The courthouse square`,`A praça do tribunal`),RM(c,'us59'),[t(`59 号国道穿过东德州一个又一个小镇。每个镇中间都有一座红砖或石头的县法院，四周围着一圈老店面，广场上有一棵老橡树和一座阵亡士兵纪念碑。`,`US-59 runs through one East Texas town after another. Each has a brick or stone county courthouse at its centre, ringed by old storefronts, with an old oak and a war memorial on the square.`,`A US-59 atravessa vilas do leste do Texas umas atrás das outras. Cada uma tem no centro um tribunal de condado de tijolo ou pedra, rodeado de lojas antigas, com um carvalho velho e um memorial de guerra na praça.`)],[
  {t:t(`停下来，在广场的咖啡馆吃早饭`,`Stop for breakfast at a café on the square`,`Parar para o pequeno-almoço num café da praça`),fx:()=>{stat('tex',2);stat('charme',1)},next:()=>say(t(`广场早餐`,`Breakfast on the square`,`Pequeno-almoço na praça`),t(`六个老头占着一张圆桌，从天气聊到橄榄球。他们问你从哪儿来，听完说：“葡萄牙？我叔叔二战时在亚速尔群岛驻过。”你们聊了一个小时。`,`Six old men hold down a round table, weather to football. They ask where you're from. "Portugal? My uncle was stationed in the Azores in the war." You talk for an hour.`,`Seis velhotes ocupam uma mesa redonda, do tempo ao futebol americano. Perguntam de onde és. «Portugal? O meu tio esteve nos Açores na guerra.» Conversam uma hora.`))},
  {t:t(`绕广场开一圈就走`,`Circle the square once and drive on`,`Dar uma volta à praça e seguir`),fx:()=>{stat('saud',1)}}])},
 {id:'tx10_us190brazos',cond:c=>HW(c,'us190'),run:c=>sc(t(`过布拉索斯河`,`Crossing the Brazos`,`A travessia do Brazos`),RM(c,'us190'),[t(`190 号国道往东，过布拉索斯河的时候，河水是红褐色的，宽而慢。两岸是棉田，秋天白得像下过雪。越往东，车尾贴着栗色标志的车越多——离大学城不远了。`,`East on US-190 you cross the Brazos, red-brown, wide and slow. Cotton fields on both banks, white as snow in the fall. The further east, the more cars wear maroon stickers — College Station isn't far.`,`Na US-190 para leste atravessas o Brazos, castanho-avermelhado, largo e lento. Algodoais nas duas margens, brancos como neve no outono. Quanto mais para leste, mais carros com autocolantes cor de vinho — College Station não está longe.`)],[
  {t:t(`在桥边停车，看河`,`Stop by the bridge and watch the river`,`Parar junto à ponte e ver o rio`),fx:()=>{stat('saud',-1);stat('tex',1)}},
  {t:t(`去路边棉花地里摘一朵寄回家`,`Pick a cotton boll from the roadside to mail home`,`Apanhar um capulho de algodão na berma para mandar para casa`),fx:()=>{stat('saud',1);stat('charme',1)},next:()=>say(t(`棉花`,`Cotton`,`Algodão`),t(`你把那朵棉花夹进给妈妈的信里。她回信说：“像云。你那边的云都长在地上吗？”`,`You tuck the boll into a letter to Mom. She writes back: "Like a cloud. Do your clouds grow on the ground over there?"`,`Metes o capulho numa carta para a mãe. Ela responde: «Parece uma nuvem. Aí as nuvens crescem no chão?»`))}])}
);
})();
